def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    import re

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cur = conn.cursor()
            cur.execute(query, params)
            rows = cur.fetchall()
            conn.close()
            return rows
        except Exception:
            return []

    # Final answer must be a non-empty string
    if not isinstance(final_answer, str) or not final_answer.strip():
        return {"result": "others"}

    text = final_answer

    # Determine user context: use user_id = 1 (the primary account in the dataset)
    user_id = 1

    # 1) Get user's active brand enrollments
    brand_rows = safe_query(final_db_path, "SELECT brand_id FROM member_brand_enrollments WHERE user_id = ? AND status = 'active'", (user_id,))
    if not brand_rows:
        return {"result": "others"}
    active_brand_ids = {r[0] for r in brand_rows}
    if not active_brand_ids:
        return {"result": "others"}

    # 2) Load all campaigns
    camp_rows = safe_query(final_db_path, "SELECT id, brand_id, name, is_active FROM campaigns", ())
    if not camp_rows:
        return {"result": "others"}

    id_to_name = {}
    name_to_id = {}
    id_to_brand = {}
    id_to_active = {}
    for cid, bid, name, is_active in camp_rows:
        id_to_name[cid] = name
        name_to_id[name] = cid
        id_to_brand[cid] = bid
        id_to_active[cid] = 1 if is_active == 1 else 0

    # 3) Active campaigns within user's active brands
    active_campaign_ids = [cid for cid in id_to_name.keys() if id_to_active.get(cid, 0) == 1 and id_to_brand.get(cid) in active_brand_ids]
    if not active_campaign_ids:
        return {"result": "others"}

    active_campaign_names = {id_to_name[cid] for cid in active_campaign_ids}

    # 4) Load user segments and campaign segments
    user_seg_rows = safe_query(final_db_path, "SELECT segment_code FROM user_segments WHERE user_id = ?", (user_id,))
    user_segments = {r[0] for r in user_seg_rows}

    camp_seg_rows = safe_query(final_db_path, "SELECT campaign_id, segment_code FROM campaign_segments", ())
    camp_to_segments = {}
    for cid, seg in camp_seg_rows:
        if cid not in camp_to_segments:
            camp_to_segments[cid] = set()
        if seg is not None:
            camp_to_segments[cid].add(seg)

    # 5) Compute expected eligibility: eligible if any overlap with user segments
    expected_eligible_ids = []
    for cid in active_campaign_ids:
        segs = camp_to_segments.get(cid, set())
        if user_segments and segs and (segs.intersection(user_segments)):
            expected_eligible_ids.append(cid)
    expected_eligible_names = {id_to_name[cid] for cid in expected_eligible_ids}

    # Helper regex logic to parse eligibility mentions in final_answer
    # Positive eligibility indicators near a campaign name (and no negative in the same snippet)
    pos_re = re.compile(r"\b(eligible|included in (?:the )?target(?:_segments?| segments?)?|in target segments?|matches (?:the )?segment|qualif(?:y|ies|ied))\b", re.IGNORECASE)
    neg_re = re.compile(r"\b(not\s+eligible|ineligible|not\s+included(?: in)? (?:the )?target(?:_segments?| segments?)?|does\s+not\s+match|doesn.?t\s+match|not\s+in\s+target|excluded)\b", re.IGNORECASE)

    def find_positions(hay: str, needle: str) -> list:
        try:
            pattern = re.compile(re.escape(needle), re.IGNORECASE)
            return [m.start() for m in pattern.finditer(hay)]
        except Exception:
            return []

    def has_positive(snippet: str) -> bool:
        return (pos_re.search(snippet) is not None) and (neg_re.search(snippet) is None)

    def has_negative(snippet: str) -> bool:
        return neg_re.search(snippet) is not None

    window = 120

    # Build sets based on mentions
    mentioned_active_names = set()
    positive_names_total = set()
    negative_names_total = set()

    all_campaign_names = list(name_to_id.keys())

    for cname in all_campaign_names:
        positions = find_positions(text, cname)
        if positions:
            if cname in active_campaign_names:
                mentioned_active_names.add(cname)
            # Analyze each mention window
            for pos in positions:
                start = pos - window
                if start < 0:
                    start = 0
                end = pos + len(cname) + window
                if end > len(text):
                    end = len(text)
                snippet = text[start:end]
                if has_positive(snippet):
                    positive_names_total.add(cname)
                if has_negative(snippet):
                    negative_names_total.add(cname)

    # 6) Validate that all active campaigns are mentioned
    if mentioned_active_names != active_campaign_names:
        return {"result": "others"}

    # 7) Validate explicit eligibility labeling: positives must match exactly expected eligible campaigns
    # No campaign outside the expected eligible set should be marked as eligible
    # Also ensure all expected eligible campaigns are positively labeled
    if not expected_eligible_names.issubset(positive_names_total):
        return {"result": "others"}
    # Ensure there are no extra positives beyond expected eligible
    if len(positive_names_total - expected_eligible_names) != 0:
        return {"result": "others"}

    # 8) Validate that all other active campaigns are explicitly marked not eligible
    ineligible_active_names = active_campaign_names - expected_eligible_names
    if not ineligible_active_names.issubset(negative_names_total):
        return {"result": "others"}

    # 9) Ensure no contradictory labeling (both positive and negative near the same active campaign)
    contradictory = (positive_names_total & negative_names_total) & active_campaign_names
    if contradictory:
        return {"result": "others"}

    return {"result": "complete"}

