### hospital_information_system_1/7
TASK: For all elective procedures scheduled at Hospital ID 1 on 2026-01-06, identify patients with infection_risk_flag true and verify that each has either an isolation or negative_pressure-capable post_op bed reserved; for any missing reservation, create a bed_request to the Infection Control ward for the required time window and log the request IDs.
--- CODE ---
def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    import re
    from datetime import datetime, timedelta

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    # Step 1: Identify elective procedures at Hospital ID 1 on 2026-01-06 with infection_risk_flag
    query_procedures = """
        SELECT p.id, p.patient_id, p.scheduled_start, p.scheduled_end, p.admission_id,
               pat.infection_risk_flag
        FROM procedures p
        JOIN patients pat ON p.patient_id = pat.id
        WHERE p.hospital_id = 1
        AND p.is_emergency = 0
        AND DATE(p.scheduled_start) = '2026-01-06'
        AND pat.infection_risk_flag = 1
    """

    procedures = safe_query(final_db_path, query_procedures)

    if not procedures:
        # No procedures match criteria - task might be trivially complete
        # But based on initial data, we expect procedures 87205, 87207 to match
        return {"result": "others"}

    # Step 2: For each procedure, check if proper post_op bed reservation exists
    patients_needing_requests = []

    for proc_id, patient_id, sched_start, sched_end, admission_id, infection_flag in procedures:
        # Check for post_op bed reservation with isolation or negative_pressure capability
        query_bed_res = """
            SELECT pbr.id, pbr.bed_id, b.is_isolation_capable, b.is_negative_pressure_capable
            FROM procedure_bed_reservations pbr
            JOIN beds b ON pbr.bed_id = b.id
            WHERE pbr.procedure_id = ?
            AND pbr.phase = 'post_op'
        """

        bed_reservations = safe_query(final_db_path, query_bed_res, (proc_id,))

        has_proper_bed = False
        for res_id, bed_id, is_iso, is_neg_press in bed_reservations:
            if is_iso == 1 or is_neg_press == 1:
                has_proper_bed = True
                break

        if not has_proper_bed:
            patients_needing_requests.append((proc_id, patient_id, admission_id, sched_start, sched_end))

    # Step 3: Verify bed_requests were created for patients missing proper reservations
    if not patients_needing_requests:
        # All patients already have proper beds - task is complete if no action needed
        # But we should verify this is the actual case
        # Based on initial data: procedure 87205 has post_op bed 60001 (isolation capable)
        # procedure 87207 has post_op bed 60001 but there's already a bed_request 2001
        # Let's check if new requests were created beyond initial state
        initial_requests = safe_query(initial_db_path, "SELECT id FROM bed_requests")
        final_requests = safe_query(final_db_path, "SELECT id FROM bed_requests")

        if len(final_requests) > len(initial_requests):
            # New requests created, need to verify them
            pass
        else:
            # No new requests and all have proper beds - check if all procedures actually have proper beds
            all_proper = True
            for proc_id, patient_id, sched_start, sched_end, admission_id, infection_flag in procedures:
                query_bed_res = """
                    SELECT pbr.id, b.is_isolation_capable, b.is_negative_pressure_capable
                    FROM procedure_bed_reservations pbr
                    JOIN beds b ON pbr.bed_id = b.id
                    WHERE pbr.procedure_id = ?
                    AND pbr.phase = 'post_op'
                """
                bed_res = safe_query(final_db_path, query_bed_res, (proc_id,))
                if not bed_res:
                    all_proper = False
                    break
                has_capability = any(is_iso == 1 or is_neg == 1 for _, is_iso, is_neg in bed_res)
                if not has_capability:
                    all_proper = False
                    break

            if all_proper:
                return {"result": "complete"}
            else:
                return {"result": "others"}

    # Step 4: Get Infection Control ward_id for Hospital 1
    infection_ward = safe_query(final_db_path, 
        "SELECT id FROM wards WHERE hospital_id = 1 AND is_infection_control = 1")

    if not infection_ward:
        return {"result": "others"}

    infection_ward_id = infection_ward[0][0]

    # Step 5: Check new bed_requests in final database
    initial_request_ids = set(row[0] for row in safe_query(initial_db_path, "SELECT id FROM bed_requests"))
    final_request_ids = set(row[0] for row in safe_query(final_db_path, "SELECT id FROM bed_requests"))

    new_request_ids = final_request_ids - initial_request_ids

    if not new_request_ids:
        return {"result": "others"}

    # Step 6: Verify new bed_requests match requirements
    for new_id in new_request_ids:
        query_request = """
            SELECT hospital_id, ward_id, patient_id, procedure_id, requested_for_phase,
                   requires_isolation, requires_negative_pressure, requested_start, requested_end
            FROM bed_requests
            WHERE id = ?
        """

        request_data = safe_query(final_db_path, query_request, (new_id,))

        if not request_data:
            return {"result": "others"}

        hosp_id, ward_id, pat_id, proc_id, phase, req_iso, req_neg, req_start, req_end = request_data[0]

        # Verify it's for Hospital 1
        if hosp_id != 1:
            return {"result": "others"}

        # Verify it's to Infection Control ward
        if ward_id != infection_ward_id:
            return {"result": "others"}

        # Verify it's for post_op phase
        if phase != 'post_op':
            return {"result": "others"}

        # Verify isolation or negative_pressure is required
        if req_iso != 1 and req_neg != 1:
            return {"result": "others"}

        # Verify it's for one of the procedures needing requests
