TASK: Using the public API, retrieve all upcoming bookings for my venues in the next 60 days, grouped by venue and space, and update any bookings with status 'tentative' whose proposal expiry_timestamp is in the past to status 'canceled'.
--- CODE ---
def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    from datetime import datetime, timedelta

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    # Calculate the date range for upcoming 60 days
    # Using a reference date to be consistent - we'll use current timestamp
    current_time = datetime.utcnow()
    sixty_days_later = current_time + timedelta(days=60)
    current_time_str = current_time.strftime('%Y-%m-%d %H:%M:%S')
    sixty_days_str = sixty_days_later.strftime('%Y-%m-%d')

    # Query to find tentative bookings in next 60 days with expired proposals in initial_db
    query_initial = """
        SELECT b.id, b.status, b.proposal_id, p.expiry_timestamp
        FROM bookings b
        LEFT JOIN proposals p ON b.proposal_id = p.id
        WHERE b.status = 'tentative'
        AND b.event_date <= ?
        AND b.event_date >= date('now')
    """

    initial_bookings = safe_query(initial_db_path, query_initial, (sixty_days_str,))

    if not initial_bookings:
        # No tentative bookings in the range, task is complete if nothing changed
        return {"result": "complete"}

    # Identify which bookings should be canceled (tentative + expired proposal)
    bookings_to_cancel = []
    for booking_id, status, proposal_id, expiry_timestamp in initial_bookings:
        if proposal_id is not None and expiry_timestamp is not None:
            try:
                expiry_dt = datetime.strptime(expiry_timestamp, '%Y-%m-%d %H:%M:%S')
                if expiry_dt < current_time:
                    bookings_to_cancel.append(booking_id)
            except (ValueError, TypeError):
                # Invalid timestamp format, skip
                continue

    if not bookings_to_cancel:
        # No bookings with expired proposals, task is complete (nothing to update)
        return {"result": "complete"}

    # Check final_db to verify these bookings are now canceled
    query_final = """
        SELECT id, status
        FROM bookings
        WHERE id IN ({})
    """.format(','.join('?' * len(bookings_to_cancel)))

    final_bookings = safe_query(final_db_path, query_final, tuple(bookings_to_cancel))

    if not final_bookings:
        # Bookings not found in final_db, something wrong
        return {"result": "others"}

    # Create a mapping of booking_id to status in final_db
    final_status_map = {booking_id: status for booking_id, status in final_bookings}

    # Verify all identified bookings are now canceled
    all_canceled = True
    for booking_id in bookings_to_cancel:
        if booking_id not in final_status_map:
            all_canceled = False
            break
        if final_status_map[booking_id] != 'canceled':
            all_canceled = False
            break

    if not all_canceled:
        return {"result": "others"}

    # Additional check: ensure no other bookings were incorrectly modified
    # Get all bookings that should NOT have been changed
    query_should_not_change = """
        SELECT id, status
        FROM bookings
        WHERE id NOT IN ({})
    """.format(','.join('?' * len(bookings_to_cancel)))

    initial_other_bookings = safe_query(initial_db_path, query_should_not_change, tuple(bookings_to_cancel))
    final_other_bookings = safe_query(final_db_path, query_should_not_change, tuple(bookings_to_cancel))

    # Convert to dictionaries for comparison
    initial_other_map = {booking_id: status for booking_id, status in initial_other_bookings}
    final_other_map = {booking_id: status for booking_id, status in final_other_bookings}

    # Check if any other booking status changed unexpectedly
    for booking_id, initial_status in initial_other_map.items():
        final_status = final_other_map.get(booking_id)
        if final_status is None:
            # Booking deleted, which is unexpected
            return {"result": "others"}
        if initial_status != final_status:
            # Status changed when it should not have
            return {"result": "others"}

    # All checks passed
    return {"result": "complete"}
