TASK: Retrieve all my orders from the last 12 months, filter for those that were refunded, and for each refunded order set the associated game licenses to status 'refunded' if they are not already marked as such.
--- CODE ---
def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    from datetime import datetime, timedelta

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    # Calculate date 12 months ago from now
    twelve_months_ago = (datetime.now() - timedelta(days=365)).strftime('%Y-%m-%d %H:%M:%S')

    # Get all refunded orders within the last 12 months from final database
    refunded_orders_query = """
        SELECT id FROM orders 
        WHERE status = 'refunded' 
        AND refunded_at IS NOT NULL
        AND refunded_at >= ?
    """
    refunded_orders = safe_query(final_db_path, refunded_orders_query, (twelve_months_ago,))

    if not refunded_orders:
        # If no refunded orders in last 12 months, task is complete (nothing to do)
        return {"result": "complete"}

    refunded_order_ids = [order[0] for order in refunded_orders]

    # For each refunded order, get all associated licenses
    all_licenses_should_be_refunded = []
    for order_id in refunded_order_ids:
        licenses_query = "SELECT id, status FROM licenses WHERE order_id = ?"
        licenses = safe_query(final_db_path, licenses_query, (order_id,))
        all_licenses_should_be_refunded.extend(licenses)

    if not all_licenses_should_be_refunded:
        # No licenses associated with refunded orders, task is complete
        return {"result": "complete"}

    # Check if ALL licenses are now marked as 'refunded'
    for license_id, status in all_licenses_should_be_refunded:
        if status != 'refunded':
            # Found a license that should be refunded but isn't
            return {"result": "others"}

    # Verify that we actually made changes (at least one license was not already refunded)
    # Get initial state of these licenses
    initial_licenses_status = {}
    for license_id, _ in all_licenses_should_be_refunded:
        initial_query = "SELECT status FROM licenses WHERE id = ?"
        initial_result = safe_query(initial_db_path, initial_query, (license_id,))
        if initial_result:
            initial_licenses_status[license_id] = initial_result[0][0]

    # Check if at least one license changed from non-refunded to refunded
    # or if all were already refunded (which is also acceptable)
    changes_made = False
    for license_id, current_status in all_licenses_should_be_refunded:
        initial_status = initial_licenses_status.get(license_id, None)
        if initial_status and initial_status != 'refunded' and current_status == 'refunded':
            changes_made = True
            break

    # If all licenses are already refunded in initial state, that's acceptable
    all_already_refunded = all(
        initial_licenses_status.get(lic_id, '') == 'refunded' 
        for lic_id, _ in all_licenses_should_be_refunded
    )

    if all_already_refunded or changes_made:
        # All licenses associated with refunded orders are now refunded
        return {"result": "complete"}

    return {"result": "others"}

