### event_management_8/8  (line 6770)
TASK: For event_id 750, generate badges for all attendees who have at least one session in their attendee_schedule but do not yet have a badge record, creating badges with badge_type 'attendee', print_status 'pending', and unique QR_code_id values derived from 'EV750-A-' plus their attendee_id.
--- CODE ---
def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    # Step 1: Find attendees with at least one session in attendee_schedule for event_id 750
    attendees_with_sessions_query = """
        SELECT DISTINCT attendee_id 
        FROM attendee_schedules 
        WHERE event_id = 750
    """
    attendees_with_sessions = safe_query(initial_db_path, attendees_with_sessions_query)

    if not attendees_with_sessions:
        # No attendees with sessions, no badges should be created
        # Check if any new badges were created in final_db
        initial_badges = safe_query(initial_db_path, "SELECT id FROM badges WHERE event_id = 750")
        final_badges = safe_query(final_db_path, "SELECT id FROM badges WHERE event_id = 750")
        if len(initial_badges) == len(final_badges):
            return {"result": "complete"}
        return {"result": "others"}

    attendee_ids_with_sessions = set(row[0] for row in attendees_with_sessions)

    # Step 2: Find attendees who already have badges for event_id 750 in initial_db
    existing_badges_query = """
        SELECT attendee_id 
        FROM badges 
        WHERE event_id = 750
    """
    existing_badges = safe_query(initial_db_path, existing_badges_query)
    attendee_ids_with_badges = set(row[0] for row in existing_badges)

    # Step 3: Calculate expected new badges (attendees with sessions but no existing badges)
    expected_new_badge_attendees = attendee_ids_with_sessions - attendee_ids_with_badges

    if not expected_new_badge_attendees:
        # No new badges should be created
        initial_badge_count = len(safe_query(initial_db_path, "SELECT id FROM badges WHERE event_id = 750"))
        final_badge_count = len(safe_query(final_db_path, "SELECT id FROM badges WHERE event_id = 750"))
        if initial_badge_count == final_badge_count:
            return {"result": "complete"}
        return {"result": "others"}

    # Step 4: Verify new badges exist in final_db with correct attributes
    new_badges_query = """
        SELECT attendee_id, badge_type, print_status, qr_code_id, event_id
        FROM badges 
        WHERE event_id = 750
    """
    final_badges = safe_query(final_db_path, new_badges_query)

    if not final_badges:
        return {"result": "others"}

    final_badge_dict = {}
    for row in final_badges:
        attendee_id, badge_type, print_status, qr_code_id, event_id = row
        final_badge_dict[attendee_id] = {
            "badge_type": badge_type,
            "print_status": print_status,
            "qr_code_id": qr_code_id,
            "event_id": event_id
        }

    # Step 5: Verify each expected attendee has a correct badge
    for attendee_id in expected_new_badge_attendees:
        if attendee_id not in final_badge_dict:
            # Missing badge for this attendee
            return {"result": "others"}

        badge = final_badge_dict[attendee_id]

        # Check badge_type is 'attendee'
        if badge["badge_type"] != "attendee":
            return {"result": "others"}

        # Check print_status is 'pending'
        if badge["print_status"] != "pending":
            return {"result": "others"}

        # Check qr_code_id follows pattern 'EV750-A-{attendee_id}'
        expected_qr_code = f"EV750-A-{attendee_id}"
        if badge["qr_code_id"] != expected_qr_code:
            return {"result": "others"}

        # Check event_id is 750
        if badge["event_id"] != 750:
            return {"result": "others"}

    # Step 6: Verify no extra badges were created (only expected attendees should have new badges)
    all_attendees_in_final = set(final_badge_dict.keys())
    expected_all_attendees = attendee_ids_with_badges.union(expected_new_badge_attendees)

    if all_attendees_in_final != expected_all_attendees:
        return {"result": "others"}

    # All checks passed
    return {"result": "complete"}

