import json, sqlite3 as real_sqlite, sys, types
from pathlib import Path
sys.path.insert(0, '/workspace/repair_tools')
from awm_replay import DATA_ROOT, create_sqlite_database, execute_sample_data, tools_jsonl_load, normalize_scenario_name

WORK = Path('/tmp/awm_vac')
db_rows = tools_jsonl_load(DATA_ROOT/'gen_db.jsonl')
sample_rows = tools_jsonl_load(DATA_ROOT/'gen_sample.jsonl')
db_by = {r['scenario']: r for r in db_rows}
sm_by = {r['scenario']: r for r in sample_rows}
sc = 'e_commerce_marketplace_19'
init = str(WORK/f'{sc}_init.db'); fin = str(WORK/f'{sc}_fin.db')
create_sqlite_database(db_by[sc]['db_schema'], init)
execute_sample_data(init, sm_by[sc]['sample_data'])
import shutil; shutil.copyfile(init, fin)

# find the rule code
code = None; line_no = None
with open(DATA_ROOT/'gen_verifier.pure_code.jsonl') as f:
    for i, ln in enumerate(f, 1):
        r = json.loads(ln)
        if normalize_scenario_name(r['scenario']) == sc and r['task_idx'] == 9:
            code = r['verification']['code']; line_no = i
            if i < 10000: break
print('rule at line', line_no)

log = []
class LogConn:
    def __init__(self, path, tag):
        self.p = str(path)
        if self.p.startswith('file:'): self.p = self.p[5:].split('?')[0]
        self.conn = real_sqlite.connect(self.p); self.cur = self.conn.cursor(); self.tag = tag
    def cursor(self): return self
    def execute(self, q, params=()):
        try:
            self.cur.execute(q, params)
            rows = self.cur.fetchall()
            log.append({'db': self.tag, 'sql': ' '.join(q.split()), 'n': len(rows), 'err': None, 'first': str(rows[:4])[:300]})
        except Exception as ex:
            log.append({'db': self.tag, 'sql': ' '.join(q.split()), 'n': 0, 'err': str(ex), 'first': ''})
            raise
        return self
    def fetchall(self): return []
    def close(self): self.conn.close()

def connect_fn(path):
    tag = 'FIN' if str(path) == fin else 'INIT'
    return LogConn(path, tag)

proxy = types.ModuleType('sqlite3')
proxy.connect = connect_fn
import sqlite3 as real_mod
for attr in ['Row','OperationalError','Error','connect']:
    if hasattr(real_mod, attr): setattr(proxy, attr, getattr(real_mod, attr))

saved = sys.modules['sqlite3']
ns = {'sqlite3': proxy, '__builtins__': __builtins__}
sys.modules['sqlite3'] = proxy
verdict = None
try:
    exec(code, ns)
    fn = ns['verify_task_completion']
    try:
        verdict = fn(initial_db_path=init, final_db_path=fin, final_answer=None)
    except TypeError:
        verdict = fn(init, fin, None)
except Exception as ex:
    verdict = f'ERROR: {ex!r}'
finally:
    sys.modules['sqlite3'] = saved

print('VERDICT on noop:', verdict)
for e in log:
    print(f"[{e['db']}] n={e['n']} err={e['err']}\n    {e['sql'][:220]}\n    → {e['first'][:280]}")
EOF

