cd /workspace/repair_tools && python3 - <<'EOF'
import json, re, sys
from datetime import datetime
sys.path.insert(0, '/workspace/repair_tools')
from awm_replay import DATA_ROOT, tools_jsonl_load, normalize_scenario_name

sample_rows = tools_jsonl_load(DATA_ROOT/'gen_sample.jsonl')
DATE_RE = re.compile(r"(20\d{2}-\d{2}-\d{2})")
DYN_RE = re.compile(r"('now'|\"now\")", re.I)

dynamic, static_anchor = set(), {}
for r in sample_rows:
    sc = normalize_scenario_name(r['scenario'])
    vals, has_dyn = [], False
    for t in r['sample_data']['tables']:
        for ins in t.get('insert_statements', []):
            if DYN_RE.search(ins) and re.search(r"date|time", ins, re.I):
                # crude: datetime('now'...) anywhere
                if re.search(r"(datetime|date|julianday|strftime)\s*\(\s*('now'|\"now\")", ins, re.I):
                    has_dyn = True
            for m in DATE_RE.finditer(ins):
                try: vals.append(datetime.strptime(m.group(1), '%Y-%m-%d'))
                except Exception: pass
    if has_dyn:
        dynamic.add(sc)
    if vals:
        a = max(vals)
        static_anchor[sc] = max(static_anchor.get(sc, a), a) if sc in static_anchor else a

print('dynamic-now scenarios:', len(dynamic), 'static-anchored:', len(static_anchor))

LIT_RE = re.compile(r"20\d{2}-\d{2}-\d{2}")
DT_RE = re.compile(r"datetime\(\s*(20\d{2})\s*,\s*(\d{1,2})\s*,\s*(\d{1,2})")

flagged = []
with open(DATA_ROOT/'gen_verifier.pure_code.jsonl') as f:
    for i, ln in enumerate(f, 1):
        if i > 10000: break
        r = json.loads(ln)
        sc = normalize_scenario_name(r['scenario'])
        code = r['verification']['code']
        task = r.get('task', '')
        dates = set()
        for m in LIT_RE.finditer(code):
            try: dates.add(datetime.strptime(m.group(0), '%Y-%m-%d'))
            except Exception: pass
        for m in DT_RE.finditer(code):
            try: dates.add(datetime(int(m.group(1)), int(m.group(2)), int(m.group(3))))
            except Exception: pass
        for d in dates:
            ds = d.strftime('%Y-%m-%d')
            if ds in task:
                continue
            if sc in dynamic:
                flagged.append({'line': i, 'scenario': r['scenario'], 'task_idx': r['task_idx'],
                                'date': ds, 'mode': 'dyn', 'anchor': None, 'dev': None})
            else:
                a = static_anchor.get(sc)
                if a and abs((d - a).days) > 90:
                    flagged.append({'line': i, 'scenario': r['scenario'], 'task_idx': r['task_idx'],
                                    'date': ds, 'mode': 'static', 'anchor': str(a.date()), 'dev': abs((d-a).days)})
            break  # one flag per rule is enough for triage

print('flagged:', len(flagged))
from collections import Counter
print(Counter(e['mode'] for e in flagged))
json.dump(flagged, open('stale_dates.json','w'), indent=1)
for e in flagged[:40]:
    print(f"  line {e['line']:5d} {e['scenario']}/{e['task_idx']} literal={e['date']} mode={e['mode']} anchor={e['anchor']} dev={e['dev']}")
EOF

