"""Dry-run structural analysis of the 1,670 newness-guard target rules.

Validates the assumptions the in-place repair (repair_rules.py) relies on,
using the exact function-selection semantics of awm.core.verify.run_verifier
(default name verify_task_completion, then first text line starting with
"def verify_"; exec namespace keeps the LAST def of a duplicated name):
  - exactly one verify_* function, no duplicate names
  - initial_db_path and final_db_path are parameters
  - no decorators, no *args/**kwargs/positional-only params
  - >=1 safe_query(final_db_path, ...) call site inside the verify body
  - no shadowed final_db_path params in nested helpers, no call sites
    outside the verify function
"""
import ast
import json
import sys
from collections import Counter
from pathlib import Path

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE))

RULES = Path("/workspace/data/AgentWorldModel-1K/gen_verifier.pure_code.jsonl")
VACUOUS_LINES = {1579, 3071, 3750, 4121, 4144, 6219, 6770, 6996, 7416, 9715}
UNPROBABLE_LINES = {5613}


def harness_func_name(code):
    func_name = "verify_task_completion"
    for line in code.split("\n"):
        line = line.strip()
        if line.startswith("def verify_") and "(" in line:
            func_name = line.split("(")[0].replace("def ", "").strip()
            break
    return func_name


def enclosing_map(tree):
    """id(node) -> list of enclosing FunctionDefs (innermost last)."""
    enc = {}

    def rec(node, stack):
        for child in ast.iter_child_nodes(node):
            newstack = stack + [child] if isinstance(
                child, (ast.FunctionDef, ast.AsyncFunctionDef)) else stack
            enc[id(child)] = newstack
            rec(child, newstack)

    rec(tree, [])
    return enc


def param_names(fn):
    a = fn.args
    return [p.arg for p in (a.posonlyargs + a.args + a.kwonlyargs)]


def main():
    mech = json.load(open(HERE / "mechanism_class.json"))
    guard = sorted({e["line"] for e in mech
                    if e["noop"] == "complete" and e["empty"] == "others"}
                   - VACUOUS_LINES - UNPROBABLE_LINES)
    print("guard targets:", len(guard))

    lines = RULES.read_text().splitlines()
    stats = Counter()
    problems = {}

    def flag(kind, ln, detail=""):
