        # payment_status must match (case-insensitive)
        if str(exp['payment_status']).lower() != str(e['payment_status']).lower():
            return {"result": "others"}

    # Extract total outstanding balance reported
    total_patterns = [
        re.compile(r"\btotal\s+outstanding\s+balance\s*[:\-]?\s*\$?\s*((?:\d{1,3}(?:,\d{3})*|\d+)(?:\.\d{1,2})?)", re.IGNORECASE),
        re.compile(r"\boutstanding\s+balance\s*[:\-]?\s*\$?\s*((?:\d{1,3}(?:,\d{3})*|\d+)(?:\.\d{1,2})?)", re.IGNORECASE)
    ]
    reported_total = None
    for pat in total_patterns:
        mt = pat.search(text)
        if mt:
            reported_total = parse_float(mt.group(1))
            break
    if reported_total is None:
        return {"result": "others"}

    # Extract count of unpaid invoices reported
    count_patterns = [
        re.compile(r"\b(?:number|count)\s+of\s+unpaid\s+invoices\s*[:\-]?\s*(\d+)", re.IGNORECASE),
        re.compile(r"\bunpaid\s+invoices\s*[:\-]?\s*(\d+)\b", re.IGNORECASE),
        re.compile(r"\bcount\s+of\s+invoices\s+.*?unpaid\s*[:\-]?\s*(\d+)", re.IGNORECASE | re.DOTALL),
        re.compile(r"\bunpaid\s+count\s*[:\-]?\s*(\d+)\b", re.IGNORECASE)
    ]
    reported_unpaid = None
    for cp in count_patterns:
        mc = cp.search(text)
        if mc:
            try:
                reported_unpaid = int(mc.group(1))
            except Exception:
                reported_unpaid = None
            if reported_unpaid is not None:
                break
    if reported_unpaid is None:
        return {"result": "others"}

    # Final validations of computed vs reported
    if abs(float(outstanding_total) - float(reported_total)) > 0.01:
        return {"result": "others"}
    if int(unpaid_count) != int(reported_unpaid):
        return {"result": "others"}

    return {"result": "complete"}


