            'payment_status': str(status).lower()
        }
        st = str(status).lower()
        if st == 'unpaid':
            unpaid_count += 1
            outstanding_total += float(amt_due)
        elif st == 'partial':
            pay_sum_rows = safe_query(final_db_path, "SELECT COALESCE(SUM(amount_paid), 0.0) FROM invoice_payments WHERE invoice_id = ?", (inv_id,))
            paid_sum = 0.0
            if pay_sum_rows and pay_sum_rows[0] and pay_sum_rows[0][0] is not None:
                try:
                    paid_sum = float(pay_sum_rows[0][0])
                except Exception:
                    paid_sum = 0.0
            remaining = float(amt_due) - paid_sum
            if remaining < 0:
                remaining = 0.0
            outstanding_total += remaining
        elif st in ('paid', 'waived'):
            # no outstanding
            pass
        else:
            # Unknown status - be conservative
            return {"result": "others"}

    # 2) Parse final_answer for six invoices and summary values
    if final_answer is None:
        return {"result": "others"}
    text = str(final_answer)
    if text.strip() == '':
        return {"result": "others"}

    # Regex to capture each invoice block with labeled fields
    # We keep bounded wildcards between labels to avoid crossing entries.
    invoice_pattern = re.compile(
        r"billing[_\s\-]?period\s*[:\-]?\s*(?P<period>20\d{2}-(0[1-9]|1[0-2]))" \
        r".{0,200}?amount[_\s\-]?due\s*[:\-]?\s*\$?\s*(?P<amount>(?:\d{1,3}(?:,\d{3})*|\d+)(?:\.\d{1,2})?)" \
        r".{0,200}?due[_\s\-]?date\s*[:\-]?\s*(?P<duedate>20\d{2}-(0[1-9]|1[0-2])-[0-3]\d)" \
        r".{0,200}?payment[_\s\-]?status\s*[:\-]?\s*(?P<status>paid|unpaid|partial|waived)",
        re.IGNORECASE | re.DOTALL
    )

    extracted = []
    for m in invoice_pattern.finditer(text):
        period = m.group('period')
        amount_s = m.group('amount')
        duedate = m.group('duedate')
        status = m.group('status').lower() if m.group('status') else None
        amt = parse_float(amount_s)
        if period and duedate and status and (amt is not None):
            extracted.append({'period': period, 'amount_due': amt, 'due_date': duedate, 'payment_status': status})

    # We require exactly 6 invoice entries to assert 'last 6 months' were provided
    if len(extracted) != 6:
        return {"result": "others"}

    # Validate periods set matches expected exactly (order may differ)
    expected_set = set(expected_periods)
    extracted_set = set([e['period'] for e in extracted])
    if extracted_set != expected_set:
