    # If no new template created, check if existing template (id=1) was updated with new sections/questions
    if not new_template:
        # Since task says "create a new", we should expect a new template, but let's be flexible
        # Check if existing template has been properly updated
        if len(final_templates) > 0:
            new_template = final_templates[0]
        else:
            return {"result": "others"}

    template_id = new_template[0]

    # Get active template version
    versions = safe_query(final_db_path,
        "SELECT id, status FROM form_template_versions WHERE form_template_id = ? AND status = 'active'",
        (template_id,)
    )

    if not versions:
        return {"result": "others"}

    version_id = versions[0][0]

    # Get sections for this version
    sections = safe_query(final_db_path,
        "SELECT id, name, display_order FROM form_sections WHERE template_version_id = ? ORDER BY display_order",
        (version_id,)
    )

    if len(sections) != 3:
        return {"result": "others"}

    # Verify section names and order
    expected_sections = ['Demographics', 'Insurance', 'Emergency Contact']
    section_map = {}

    for i, section in enumerate(sections):
        section_id, section_name, display_order = section
        if display_order != i + 1:
            return {"result": "others"}
        if section_name not in expected_sections:
            return {"result": "others"}
        section_map[section_name] = section_id

    # Verify all expected sections are present
    if set(section_map.keys()) != set(expected_sections):
        return {"result": "others"}

    # Check Demographics section for required short_text and date questions with validation
    demo_section_id = section_map['Demographics']
    demo_questions = safe_query(final_db_path,
        "SELECT id, question_type, is_required, validation_rules FROM questions WHERE section_id = ?",
        (demo_section_id,)
    )

    if not demo_questions:
        return {"result": "others"}

    has_required_short_text = False
    has_required_date = False

    for q in demo_questions:
        q_id, q_type, is_req, val_rules = q
        if q_type == 'short_text' and is_req == 1 and val_rules:
            has_required_short_text = True
        if q_type == 'date' and is_req == 1 and val_rules:
            has_required_date = True

    if not (has_required_short_text and has_required_date):
        return {"result": "others"}

    # Check Emergency Contact section for yes_no question
    ec_section_id = section_map['Emergency Contact']
    ec_questions = safe_query(final_db_path,
        "SELECT id, question_type, is_required FROM questions WHERE section_id = ? AND question_type = 'yes_no'",
        (ec_section_id,)
    )

    if not ec_questions:
        return {"result": "others"}

    yes_no_question_id = None
    for q in ec_questions:
        if q[2] == 1:  # is_required
            yes_no_question_id = q[0]
            break

    if not yes_no_question_id:
        return {"result": "others"}

    # Check for conditional logic on yes_no question
    conditions = safe_query(final_db_path,
        "SELECT id, source_question_id, operator, expected_value, target_question_id, action FROM question_conditions WHERE template_version_id = ? AND source_question_id = ?",
        (version_id, yes_no_question_id)
    )

    if not conditions:
        return {"result": "others"}

    # Verify at least one condition with 'show' action when answered 'Yes'
    has_yes_show_condition = False
    target_question_ids = []

    for cond in conditions:
        cond_id, src_q_id, operator, expected_val, target_q_id, action = cond
        if operator.lower() == 'equals' and expected_val and expected_val.lower() == 'yes' and action.lower() == 'show' and target_q_id:
            has_yes_show_condition = True
            target_question_ids.append(target_q_id)

    if not has_yes_show_condition:
        return {"result": "others"}

    # Verify target questions are contact fields (short_text type)
    for target_q_id in target_question_ids:
        target_q = safe_query(final_db_path,
            "SELECT question_type FROM questions WHERE id = ?",
            (target_q_id,)
        )
        if not target_q or target_q[0][0] != 'short_text':
            return {"result": "others"}

    # All checks passed
    return {"result": "complete"}

