def _awm_orig_verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None, _awm_ev=None) -> dict:
    def _awm_probe_final(query, *params, **kw):
        """AWM repair: run the rule's own final-DB query and compare against the initial DB."""
        try:
            _awm_rows = safe_query(final_db_path, query, *params, **kw)
        except Exception:
            return []
        _awm_diff = True  # cannot compare -> assume a difference (stay complete)
        try:
            if isinstance(_awm_rows, (list, tuple)):
                _awm_init = safe_query(initial_db_path, query, *params, **kw)
                _awm_diff = (list(_awm_rows) != list(_awm_init))
        except Exception:
            _awm_diff = True
        try:
            _awm_ev.append(_awm_diff)
        except Exception:
            pass
        return _awm_rows
    import sqlite3
    import re

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    # Step 1: Find the Templates workspace (workspace_id=2 based on initial data)
    workspace_query = "SELECT id FROM workspaces WHERE name = 'Templates' AND is_template_space = 1"
    initial_workspaces = safe_query(initial_db_path, workspace_query)
    final_workspaces = _awm_probe_final(workspace_query)

    if not final_workspaces:
        return {"result": "others"}

    templates_workspace_id = final_workspaces[0][0]

    # Step 2: Check if document 'API Design Template v2' exists in final but not in initial
    doc_query = "SELECT id, workspace_id, type, is_template FROM documents WHERE title = 'API Design Template v2'"
    initial_docs = safe_query(initial_db_path, doc_query)
    final_docs = _awm_probe_final(doc_query)

    # Should be exactly 1 document in final
    # AWM repair: the seeded data already contains an 'API Design
    # Template v2' document, so a genuine completion that creates its
    # own would produce two matches and fail this exactly-one check.
    # Restrict the strict count to documents the episode itself
    # created; fall back to the seeded row when it created none
    # (in-place edits of the seeded document still verify; the
    # newness guard rejects a do-nothing episode).
    initial_doc_ids = set(row[0] for row in
                          safe_query(initial_db_path, doc_query))
    episode_docs = [d for d in final_docs if d[0] not in initial_doc_ids]
    if episode_docs:
        final_docs = episode_docs

    if len(final_docs) != 1:
        return {"result": "others"}

    doc_id, workspace_id, doc_type, is_template = final_docs[0]

    # Verify document attributes
    if workspace_id != templates_workspace_id:
        return {"result": "others"}

    if doc_type != 'plan':
        return {"result": "others"}

    if is_template != 1:
        return {"result": "others"}

    # Step 3: Verify the document has exactly 4 sections with correct headings
    sections_query = "SELECT heading, position FROM document_sections WHERE document_id = ? ORDER BY position"
    initial_sections = safe_query(initial_db_path, sections_query, (doc_id,))
    final_sections = _awm_probe_final(sections_query, (doc_id,))

    # Should have 4 sections
    if len(final_sections) != 4:
        return {"result": "others"}

    # Check expected section headings and positions
    expected_sections = [
        ('Overview', 1),
        ('Requirements', 2),
        ('API Endpoints', 3),
        ('Risks', 4)
    ]

    for i, (heading, position) in enumerate(expected_sections):
        if i >= len(final_sections):
            return {"result": "others"}

        actual_heading, actual_position = final_sections[i]
        if actual_heading != heading or actual_position != position:
            return {"result": "others"}

    # Step 4: Verify permissions
    perms_query = "SELECT scope, role FROM document_permissions WHERE document_id = ?"
    initial_perms = safe_query(initial_db_path, perms_query, (doc_id,))
    final_perms = _awm_probe_final(perms_query, (doc_id,))

    # Should have at least 2 permission entries
    if len(final_perms) < 2:
        return {"result": "others"}

    # Check for required permissions
    perms_dict = {scope: role for scope, role in final_perms}

    # org_owners should be owner
    if perms_dict.get('org_owners') != 'owner':
        return {"result": "others"}

    # workspace_members should be editor
    if perms_dict.get('workspace_members') != 'editor':
        return {"result": "others"}

    # All checks passed
    return {"result": "complete"}

