def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    import re

    # Helper to safely query database
    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    def parse_float(num_str: str):
        if num_str is None:
            return None
        s = str(num_str).strip()
        # Remove currency symbol and commas/spaces
        s = s.replace('$', '').replace(',', '').strip()
        # Must be a valid number
        m = re.fullmatch(r"[-+]?\d*(?:\.\d+)?", s)
        if not m or s == '' or s == '+' or s == '-':
            return None
        try:
            return float(s)
        except Exception:
            return None

    # 1) Build ground truth from final DB
    # Get community id for 'Hillcrest Estates'
    comm_rows = safe_query(final_db_path, "SELECT id FROM communities WHERE name = ?", ("Hillcrest Estates",))
    if not comm_rows or not comm_rows[0] or comm_rows[0][0] is None:
        return {"result": "others"}
    community_id = comm_rows[0][0]

    # Get unit id for unit_number '3C' within this community
    unit_rows = safe_query(final_db_path, "SELECT id FROM units WHERE community_id = ? AND unit_number = ?", (community_id, '3C'))
    if not unit_rows or not unit_rows[0] or unit_rows[0][0] is None:
        return {"result": "others"}
    unit_id = unit_rows[0][0]

    # Get all invoices for this unit ordered by billing_period DESC
    inv_rows_desc = safe_query(final_db_path, "SELECT id, billing_period, amount_due, due_date, payment_status FROM dues_invoices WHERE unit_id = ? ORDER BY billing_period DESC", (unit_id,))
    if not inv_rows_desc or len(inv_rows_desc) < 6:
        # Need at least 6 to satisfy 'last 6 months'
        return {"result": "others"}

    latest6 = inv_rows_desc[:6]

    # Prepare expected data structures
    expected_periods = []
    expected_details = {}  # period -> dict(amount_due, due_date, payment_status, invoice_id)

    outstanding_total = 0.0
    unpaid_count = 0

    for (inv_id, period, amt_due, due_date, status) in latest6:
        if period is None or due_date is None or status is None:
            return {"result": "others"}
        expected_periods.append(period)
        expected_details[period] = {
            'invoice_id': inv_id,
            'amount_due': float(amt_due) if amt_due is not None else None,
            'due_date': str(due_date),
            'payment_status': str(status).lower()
        }
        st = str(status).lower()
        if st == 'unpaid':
            unpaid_count += 1
            outstanding_total += float(amt_due)
        elif st == 'partial':
            pay_sum_rows = safe_query(final_db_path, "SELECT COALESCE(SUM(amount_paid), 0.0) FROM invoice_payments WHERE invoice_id = ?", (inv_id,))
            paid_sum = 0.0
            if pay_sum_rows and pay_sum_rows[0] and pay_sum_rows[0][0] is not None:
                try:
                    paid_sum = float(pay_sum_rows[0][0])
                except Exception:
                    paid_sum = 0.0
            remaining = float(amt_due) - paid_sum
            if remaining < 0:
                remaining = 0.0
            outstanding_total += remaining
        elif st in ('paid', 'waived'):
            # no outstanding
            pass
        else:
            # Unknown status - be conservative
            return {"result": "others"}

    # 2) Parse final_answer for six invoices and summary values
    if final_answer is None:
        return {"result": "others"}
    text = str(final_answer)
    if text.strip() == '':
        return {"result": "others"}

    # Regex to capture each invoice block with labeled fields
    # We keep bounded wildcards between labels to avoid crossing entries.
    invoice_pattern = re.compile(
        r"billing[_\s\-]?period\s*[:\-]?\s*(?P<period>20\d{2}-(0[1-9]|1[0-2]))" \
        r".{0,200}?amount[_\s\-]?due\s*[:\-]?\s*\$?\s*(?P<amount>(?:\d{1,3}(?:,\d{3})*|\d+)(?:\.\d{1,2})?)" \
        r".{0,200}?due[_\s\-]?date\s*[:\-]?\s*(?P<duedate>20\d{2}-(0[1-9]|1[0-2])-[0-3]\d)" \
        r".{0,200}?payment[_\s\-]?status\s*[:\-]?\s*(?P<status>paid|unpaid|partial|waived)",
        re.IGNORECASE | re.DOTALL
    )

    extracted = []
    for m in invoice_pattern.finditer(text):
        period = m.group('period')
        amount_s = m.group('amount')
        duedate = m.group('duedate')
        status = m.group('status').lower() if m.group('status') else None
        amt = parse_float(amount_s)
        if period and duedate and status and (amt is not None):
            extracted.append({'period': period, 'amount_due': amt, 'due_date': duedate, 'payment_status': status})

    # We require exactly 6 invoice entries to assert 'last 6 months' were provided
    if len(extracted) != 6:
        return {"result": "others"}

    # Validate periods set matches expected exactly (order may differ)
    expected_set = set(expected_periods)
    extracted_set = set([e['period'] for e in extracted])
    if extracted_set != expected_set:
        return {"result": "others"}

    # Validate each invoice's fields match DB
    for e in extracted:
        period = e['period']
        if period not in expected_details:
            return {"result": "others"}
        exp = expected_details[period]
        # amount_due must match exactly within 0.01
        if exp['amount_due'] is None:
            return {"result": "others"}
        if abs(float(exp['amount_due']) - float(e['amount_due'])) > 0.01:
            return {"result": "others"}
        # due_date must match exactly
        if str(exp['due_date']) != str(e['due_date']):
            return {"result": "others"}
        # payment_status must match (case-insensitive)
        if str(exp['payment_status']).lower() != str(e['payment_status']).lower():
            return {"result": "others"}

    # Extract total outstanding balance reported
    total_patterns = [
        re.compile(r"\btotal\s+outstanding\s+balance\s*[:\-]?\s*\$?\s*((?:\d{1,3}(?:,\d{3})*|\d+)(?:\.\d{1,2})?)", re.IGNORECASE),
        re.compile(r"\boutstanding\s+balance\s*[:\-]?\s*\$?\s*((?:\d{1,3}(?:,\d{3})*|\d+)(?:\.\d{1,2})?)", re.IGNORECASE)
    ]
    reported_total = None
    for pat in total_patterns:
        mt = pat.search(text)
        if mt:
            reported_total = parse_float(mt.group(1))
            break
    if reported_total is None:
        return {"result": "others"}

    # Extract count of unpaid invoices reported
    count_patterns = [
        re.compile(r"\b(?:number|count)\s+of\s+unpaid\s+invoices\s*[:\-]?\s*(\d+)", re.IGNORECASE),
        re.compile(r"\bunpaid\s+invoices\s*[:\-]?\s*(\d+)\b", re.IGNORECASE),
        re.compile(r"\bcount\s+of\s+invoices\s+.*?unpaid\s*[:\-]?\s*(\d+)", re.IGNORECASE | re.DOTALL),
        re.compile(r"\bunpaid\s+count\s*[:\-]?\s*(\d+)\b", re.IGNORECASE)
    ]
    reported_unpaid = None
    for cp in count_patterns:
        mc = cp.search(text)
        if mc:
            try:
                reported_unpaid = int(mc.group(1))
            except Exception:
                reported_unpaid = None
            if reported_unpaid is not None:
                break
    if reported_unpaid is None:
        return {"result": "others"}

    # Final validations of computed vs reported
    if abs(float(outstanding_total) - float(reported_total)) > 0.01:
        return {"result": "others"}
    if int(unpaid_count) != int(reported_unpaid):
        return {"result": "others"}

    return {"result": "complete"}

