    def parse_utc_dt(s: str):
        if not s or not isinstance(s, str):
            return None
        s = s.strip()
        fmt = "%Y-%m-%d %H:%M:%S"
        try:
            dt = datetime.strptime(s, fmt)
        except Exception:
            # try trimming microseconds if present
            try:
                # handle cases like 'YYYY-MM-DD HH:MM:SS.sss'
                base = s.split(".")[0]
                dt = datetime.strptime(base, fmt)
            except Exception:
                return None
        return dt.replace(tzinfo=timezone.utc)

    def compute_next_friday_2030_utc(created_at_utc: datetime, tz_name: str):
        if created_at_utc is None:
            return None
        if not tz_name or not isinstance(tz_name, str):
            tz_name = "UTC"
        if ZoneInfo is None:
            return None
        try:
            tz = ZoneInfo(tz_name)
        except Exception:
            return None
        local_dt = created_at_utc.astimezone(tz)
        weekday = local_dt.weekday()  # Mon=0 .. Sun=6
        target_weekday = 4  # Friday
        days_ahead = (target_weekday - weekday) % 7
        target_local_time = time(20, 30, 0)
        if days_ahead == 0 and (local_dt.time() >= target_local_time):
            days_ahead = 7
        target_date = (local_dt.date() + timedelta(days=days_ahead))
        target_local_dt = datetime.combine(target_date, target_local_time, tzinfo=tz)
        return target_local_dt.astimezone(timezone.utc)

    # 1) Resolve current user and timezone from final DB
    user_rows = safe_query(final_db_path, "SELECT id, timezone FROM users WHERE username = ? LIMIT 1", ("current_user",))
