        # 5) Verify both media items are linked to this room
        rmi_rows = safe_query(final_db_path, "SELECT media_item_id FROM room_media_items WHERE room_id = ?", (room_id,))
        linked_ids = {row[0] for row in rmi_rows if row and row[0] is not None}
