def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    import re
    from datetime import datetime, date

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            conn.row_factory = sqlite3.Row
            cur = conn.cursor()
            cur.execute(query, params)
            rows = cur.fetchall()
            conn.close()
            return rows
        except Exception:
            return []

    def parse_date_str(s: str) -> date | None:
        if not s or not isinstance(s, str):
            return None
        s = s.strip()
        # Try common ISO formats
        for fmt in ("%Y-%m-%d", "%Y-%m-%d %H:%M:%S", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%d %H:%M:%S.%f", "%Y-%m-%dT%H:%M:%S.%f"):
            try:
                dt = datetime.strptime(s, fmt)
                return dt.date()
            except Exception:
                continue
        # If string may already be date-like but with timezone, strip timezone info
        tz_idx = max(s.find("+"), s.find("-", 10))
        if tz_idx > 0:
            try:
                dt = datetime.fromisoformat(s[:tz_idx])
                return dt.date()
            except Exception:
                pass
        try:
            dt = datetime.fromisoformat(s)
            return dt.date()
        except Exception:
            return None

    def max_nullable_date(dates: list[date]) -> date | None:
        vals = [d for d in dates if isinstance(d, date)]
        if not vals:
            return None
        return max(vals)

    def get_reference_date(db_path: str) -> date | None:
        # Collect maximum dates from several relevant tables/columns
        candidates: list[date] = []
        # donations.donated_at
        rows = safe_query(db_path, "SELECT MAX(donated_at) AS m FROM donations")
        if rows and rows[0][0] is not None:
            d = parse_date_str(rows[0][0])
            if d: candidates.append(d)
        # campaigns.updated_at
        rows = safe_query(db_path, "SELECT MAX(updated_at) AS m FROM campaigns")
        if rows and rows[0][0] is not None:
            d = parse_date_str(rows[0][0])
            if d: candidates.append(d)
        # recurring_donation_schedules.updated_at and created_at
        rows = safe_query(db_path, "SELECT MAX(updated_at) AS m, MAX(created_at) AS c FROM recurring_donation_schedules")
        if rows:
            if rows[0][0] is not None:
                d = parse_date_str(rows[0][0])
                if d: candidates.append(d)
            if rows[0][1] is not None:
                d = parse_date_str(rows[0][1])
                if d: candidates.append(d)
        # payout_batches.scheduled_payout_date
        rows = safe_query(db_path, "SELECT MAX(scheduled_payout_date) AS m FROM payout_batches")
        if rows and rows[0][0] is not None:
            d = parse_date_str(rows[0][0])
            if d: candidates.append(d)
        # campaign_updates.posted_at
        rows = safe_query(db_path, "SELECT MAX(posted_at) AS m FROM campaign_updates")
        if rows and rows[0][0] is not None:
            d = parse_date_str(rows[0][0])
            if d: candidates.append(d)
        return max_nullable_date(candidates)

    def first_day_next_month(d: date) -> str:
        # Returns YYYY-MM-DD for the first day of the next month
        year = d.year
        month = d.month
        if month == 12:
            return f"{year+1:04d}-01-01"
        else:
            return f"{year:04d}-{month+1:02d}-01"

    def get_current_user_id(db_path: str) -> int | None:
        # Prefer username 'current_user'
        rows = safe_query(db_path, "SELECT id FROM users WHERE username = ?", ("current_user",))
        if len(rows) == 1 and rows[0][0] is not None:
            try:
                return int(rows[0][0])
            except Exception:
                return None
        # Fallback: unique user with role donor_owner in profile_data
        rows = safe_query(db_path, "SELECT id FROM users WHERE profile_data LIKE '%donor_owner%'")
        if len(rows) == 1 and rows[0][0] is not None:
            try:
                return int(rows[0][0])
            except Exception:
                return None
        return None

    def get_campaign_id_by_name(db_path: str, name: str) -> int | None:
        rows = safe_query(db_path, "SELECT id FROM campaigns WHERE name = ?", (name,))
        if len(rows) != 1:
            return None
        try:
            return int(rows[0][0])
        except Exception:
            return None

    def get_payment_method_id(db_path: str, user_id: int, brand: str, last4: str) -> int | None:
        rows = safe_query(db_path, "SELECT id FROM payment_methods WHERE user_id = ? AND UPPER(brand) = UPPER(?) AND last4 = ?", (user_id, brand, last4))
        if len(rows) != 1:
            return None
        try:
            return int(rows[0][0])
        except Exception:
            return None

    def count_matching_schedules(db_path: str, user_id: int, campaign_id: int, payment_method_id: int, start_date: str) -> int:
        q = (
            "SELECT COUNT(1) FROM recurring_donation_schedules "
            "WHERE user_id = ? AND campaign_id = ? AND payment_method_id = ? "
            "AND CAST(amount AS REAL) = 50.0 AND UPPER(currency) = 'USD' "
            "AND interval_unit = 'month' AND interval_count = 1 "
            "AND start_date = ? AND status = 'active' "
            "AND stop_when_campaign_complete = 1 AND end_date IS NULL"
        )
        rows = safe_query(db_path, q, (user_id, campaign_id, payment_method_id, start_date))
        if not rows:
            return 0
        try:
            return int(rows[0][0])
        except Exception:
            return 0

    # 1) Resolve entities in final DB for determinism
    user_id = get_current_user_id(final_db_path)
    if user_id is None:
        return {"result": "others"}

    campaign_id = get_campaign_id_by_name(final_db_path, "Community Health Clinic Supplies")
    if campaign_id is None:
        return {"result": "others"}

    pm_id = get_payment_method_id(final_db_path, user_id, "VISA", "4242")
    if pm_id is None:
        return {"result": "others"}

    # 2) Compute expected start_date from reference date
    ref_date = get_reference_date(final_db_path)
    if ref_date is None:
        # Fallback to initial DB
        ref_date = get_reference_date(initial_db_path)
    if ref_date is None:
        return {"result": "others"}
    expected_start = first_day_next_month(ref_date)

    # 3) Count matching schedules in both DBs
    init_user_id = get_current_user_id(initial_db_path)
    # If user_id differs across DBs or missing in initial, we still proceed with final verification but need count in initial; if missing, treat as 0 to avoid false positives
    if init_user_id is None:
        init_user_id = user_id
    init_campaign_id = get_campaign_id_by_name(initial_db_path, "Community Health Clinic Supplies")
    if init_campaign_id is None:
        init_campaign_id = campaign_id
    init_pm_id = get_payment_method_id(initial_db_path, init_user_id, "VISA", "4242")
    if init_pm_id is None:
        init_pm_id = pm_id

    initial_count = count_matching_schedules(initial_db_path, init_user_id, init_campaign_id, init_pm_id, expected_start)
    final_count = count_matching_schedules(final_db_path, user_id, campaign_id, pm_id, expected_start)

    # 4) Decide result strictly: must be a net increase in matching schedules
    if final_count >= initial_count + 1 and final_count >= 1:
        return {"result": "complete"}

    return {"result": "others"}

def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    import re

    # Helper: run a read-only query safely; return empty list on any DB error
    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cur = conn.cursor()
            cur.execute(query, params)
            rows = cur.fetchall()
            conn.close()
            return rows
        except Exception:
            return []

    expected_title = "How to fix TypeError: unsupported operand type(s) for +: int and str in Python?"
    required_tags = {"python", "typeerror", "python-3.x"}
    current_user_id = 1

    # 1) Collect initial question IDs with the exact title
    initial_q_rows = safe_query(
        initial_db_path,
        "SELECT id FROM questions WHERE title = ?",
        (expected_title,)
    )
    initial_ids = {row[0] for row in initial_q_rows if isinstance(row, tuple) and len(row) > 0 and isinstance(row[0], int)}

    # 2) Get final questions with the exact title
    final_q_rows = safe_query(
        final_db_path,
        "SELECT id, owner_user_id, body FROM questions WHERE title = ?",
        (expected_title,)
    )

    if not final_q_rows:
        return {"result": "others"}

    # Precompile regex patterns
    py311_re = re.compile(r"python\s*3\.11", re.IGNORECASE)
    code_re = re.compile(r"(?i)total\s*=\s*5\s*\+\s*'3'")

    # Helper to get tag names for a question id in final DB
    def get_tag_names_for_question(qid: int) -> set:
        rows = safe_query(
            final_db_path,
            "SELECT t.name FROM question_tags qt JOIN tags t ON t.id = qt.tag_id WHERE qt.question_id = ?",
            (qid,)
        )
        names = set()
        for r in rows:
            if isinstance(r, tuple) and len(r) > 0 and isinstance(r[0], str):
                names.add(r[0].strip().lower())
        return names

    # 3) Validate existence of a new qualifying question
    for row in final_q_rows:
        if not (isinstance(row, tuple) and len(row) >= 3):
            continue
        qid, owner_user_id, body = row[0], row[1], row[2]
        # Must be a new question (id not present in initial set)
        if not isinstance(qid, int) or qid in initial_ids:
            continue
        # Must be owned by current_user
        if owner_user_id != current_user_id:
            continue
        # Body checks
        if not isinstance(body, str) or body.strip() == "":
            continue
        if py311_re.search(body) is None:
            continue
        if code_re.search(body) is None:
            continue
        # Tag checks: required tags must be included
        tag_names = get_tag_names_for_question(qid)
        if not tag_names:
            continue
        if not required_tags.issubset(tag_names):
            continue
        # All checks passed for this new question
        return {"result": "complete"}

    return {"result": "others"}

def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    from datetime import datetime, timedelta

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    # AWM repair: derive the reference date from the most recent
    # timestamps in the database (sample data is seeded relative to
    # runtime "now", so the hardcoded generator-era date went stale).
    _awm_ref_rows = safe_query(initial_db_path, """
        SELECT MAX(ts) FROM (
            SELECT MAX(updated_at) AS ts FROM orders
            UNION ALL
            SELECT MAX(created_at) AS ts FROM orders
            UNION ALL
            SELECT MAX(closet_created_at) AS ts FROM listings
        )
    """)
    try:
        reference_date = (_awm_ref_rows[0][0] if _awm_ref_rows and _awm_ref_rows[0][0]
                         else datetime.now().strftime('%Y-%m-%d %H:%M:%S'))
        ref_dt = datetime.strptime(reference_date, '%Y-%m-%d %H:%M:%S')
        threshold_date = ref_dt - timedelta(days=90)
        threshold_str = threshold_date.strftime('%Y-%m-%d %H:%M:%S')
    except Exception:
        return {"result": "others"}

    # Get active listings from main_seller (user_id=1) in initial state
    initial_query = """
        SELECT id, listing_price_cents, closet_created_at
        FROM listings
        WHERE seller_id = 1 AND status = 'active'
    """
    initial_listings = safe_query(initial_db_path, initial_query)

    if not initial_listings:
        return {"result": "others"}

    # Get all orders to identify listings that have been sold
    orders_query = "SELECT DISTINCT listing_id FROM orders"
    sold_listing_ids = set(row[0] for row in safe_query(initial_db_path, orders_query))

    # Identify listings that qualify for price reduction
    # Criteria: active, closet_created_at > 90 days ago, never sold
    qualifying_listings = []
    for listing_id, price_cents, closet_created_at in initial_listings:
        # Skip if listing has been sold
        if listing_id in sold_listing_ids:
            continue

        # Check if closet_created_at is more than 90 days ago
        try:
            if closet_created_at and closet_created_at < threshold_str:
                qualifying_listings.append((listing_id, price_cents))
        except Exception:
            continue

    # AWM repair: no qualifying listings means nothing needed a price
    # reduction (on this data the >90-day active listings have all been
    # sold) - fall through to the unchanged-price check below, which
    # accepts an untouched DB and rejects price changes on
    # non-qualifying listings.

    # Get final state of all listings from seller_id=1
    final_query = """
        SELECT id, listing_price_cents
        FROM listings
        WHERE seller_id = 1
    """
    final_listings = safe_query(final_db_path, final_query)

    if not final_listings:
        return {"result": "others"}

    # Create a map of final prices
    final_prices = {listing_id: price for listing_id, price in final_listings}

    # Verify that all qualifying listings have 20% price reduction
    all_reduced_correctly = True
    for listing_id, initial_price in qualifying_listings:
        if listing_id not in final_prices:
            return {"result": "others"}

        final_price = final_prices[listing_id]
        expected_price = int(initial_price * 0.8)

        # Allow for minor rounding differences (within 1 cent)
        if abs(final_price - expected_price) > 1:
            all_reduced_correctly = False
            break

    if not all_reduced_correctly:
        return {"result": "others"}

    # Verify that non-qualifying listings from seller_id=1 remain unchanged
    initial_prices_map = {listing_id: price for listing_id, price, _ in initial_listings}

    for listing_id, initial_price, _ in initial_listings:
        # Skip qualifying listings (already checked)
        if any(ql[0] == listing_id for ql in qualifying_listings):
            continue

        if listing_id in final_prices:
            # Non-qualifying listings should have unchanged prices
            if final_prices[listing_id] != initial_price:
                return {"result": "others"}

    # All checks passed
    return {"result": "complete"}

def _awm_orig_verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None, _awm_ev=None) -> dict:
    def _awm_probe_final(query, *params, **kw):
