def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    import re

    # Helper to safely query database
    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    def parse_float(num_str: str):
        if num_str is None:
            return None
        s = str(num_str).strip()
        # Remove currency symbol and commas/spaces
        s = s.replace('$', '').replace(',', '').strip()
        # Must be a valid number
        m = re.fullmatch(r"[-+]?\d*(?:\.\d+)?", s)
        if not m or s == '' or s == '+' or s == '-':
            return None
        try:
            return float(s)
        except Exception:
            return None

    # 1) Build ground truth from final DB
    # Get community id for 'Hillcrest Estates'
    comm_rows = safe_query(final_db_path, "SELECT id FROM communities WHERE name = ?", ("Hillcrest Estates",))
    if not comm_rows or not comm_rows[0] or comm_rows[0][0] is None:
        return {"result": "others"}
    community_id = comm_rows[0][0]

    # Get unit id for unit_number '3C' within this community
    unit_rows = safe_query(final_db_path, "SELECT id FROM units WHERE community_id = ? AND unit_number = ?", (community_id, '3C'))
    if not unit_rows or not unit_rows[0] or unit_rows[0][0] is None:
        return {"result": "others"}
    unit_id = unit_rows[0][0]

    # Get all invoices for this unit ordered by billing_period DESC
    inv_rows_desc = safe_query(final_db_path, "SELECT id, billing_period, amount_due, due_date, payment_status FROM dues_invoices WHERE unit_id = ? ORDER BY billing_period DESC", (unit_id,))
    if not inv_rows_desc or len(inv_rows_desc) < 6:
        # Need at least 6 to satisfy 'last 6 months'
        return {"result": "others"}

    latest6 = inv_rows_desc[:6]

    # Prepare expected data structures
    expected_periods = []
    expected_details = {}  # period -> dict(amount_due, due_date, payment_status, invoice_id)

    outstanding_total = 0.0
    unpaid_count = 0

    for (inv_id, period, amt_due, due_date, status) in latest6:
        if period is None or due_date is None or status is None:
            return {"result": "others"}
        expected_periods.append(period)
        expected_details[period] = {
            'invoice_id': inv_id,
            'amount_due': float(amt_due) if amt_due is not None else None,
            'due_date': str(due_date),
            'payment_status': str(status).lower()
        }
        st = str(status).lower()
        if st == 'unpaid':
            unpaid_count += 1
            outstanding_total += float(amt_due)
        elif st == 'partial':
            pay_sum_rows = safe_query(final_db_path, "SELECT COALESCE(SUM(amount_paid), 0.0) FROM invoice_payments WHERE invoice_id = ?", (inv_id,))
            paid_sum = 0.0
            if pay_sum_rows and pay_sum_rows[0] and pay_sum_rows[0][0] is not None:
                try:
                    paid_sum = float(pay_sum_rows[0][0])
                except Exception:
                    paid_sum = 0.0
            remaining = float(amt_due) - paid_sum
            if remaining < 0:
                remaining = 0.0
            outstanding_total += remaining
        elif st in ('paid', 'waived'):
            # no outstanding
            pass
        else:
            # Unknown status - be conservative
            return {"result": "others"}

    # 2) Parse final_answer for six invoices and summary values
    if final_answer is None:
        return {"result": "others"}
    text = str(final_answer)
    if text.strip() == '':
        return {"result": "others"}

    # Regex to capture each invoice block with labeled fields
    # We keep bounded wildcards between labels to avoid crossing entries.
    invoice_pattern = re.compile(
        r"billing[_\s\-]?period\s*[:\-]?\s*(?P<period>20\d{2}-(0[1-9]|1[0-2]))" \
        r".{0,200}?amount[_\s\-]?due\s*[:\-]?\s*\$?\s*(?P<amount>(?:\d{1,3}(?:,\d{3})*|\d+)(?:\.\d{1,2})?)" \
        r".{0,200}?due[_\s\-]?date\s*[:\-]?\s*(?P<duedate>20\d{2}-(0[1-9]|1[0-2])-[0-3]\d)" \
        r".{0,200}?payment[_\s\-]?status\s*[:\-]?\s*(?P<status>paid|unpaid|partial|waived)",
        re.IGNORECASE | re.DOTALL
    )

    extracted = []
    for m in invoice_pattern.finditer(text):
        period = m.group('period')
        amount_s = m.group('amount')
        duedate = m.group('duedate')
        status = m.group('status').lower() if m.group('status') else None
        amt = parse_float(amount_s)
        if period and duedate and status and (amt is not None):
            extracted.append({'period': period, 'amount_due': amt, 'due_date': duedate, 'payment_status': status})

    # We require exactly 6 invoice entries to assert 'last 6 months' were provided
    if len(extracted) != 6:
        return {"result": "others"}

    # Validate periods set matches expected exactly (order may differ)
    expected_set = set(expected_periods)
    extracted_set = set([e['period'] for e in extracted])
    if extracted_set != expected_set:
        return {"result": "others"}

    # Validate each invoice's fields match DB
    for e in extracted:
        period = e['period']
        if period not in expected_details:
            return {"result": "others"}
        exp = expected_details[period]
        # amount_due must match exactly within 0.01
        if exp['amount_due'] is None:
            return {"result": "others"}
        if abs(float(exp['amount_due']) - float(e['amount_due'])) > 0.01:
            return {"result": "others"}
        # due_date must match exactly
        if str(exp['due_date']) != str(e['due_date']):
            return {"result": "others"}
        # payment_status must match (case-insensitive)
        if str(exp['payment_status']).lower() != str(e['payment_status']).lower():
            return {"result": "others"}

    # Extract total outstanding balance reported
    total_patterns = [
        re.compile(r"\btotal\s+outstanding\s+balance\s*[:\-]?\s*\$?\s*((?:\d{1,3}(?:,\d{3})*|\d+)(?:\.\d{1,2})?)", re.IGNORECASE),
        re.compile(r"\boutstanding\s+balance\s*[:\-]?\s*\$?\s*((?:\d{1,3}(?:,\d{3})*|\d+)(?:\.\d{1,2})?)", re.IGNORECASE)
    ]
    reported_total = None
    for pat in total_patterns:
        mt = pat.search(text)
        if mt:
            reported_total = parse_float(mt.group(1))
            break
    if reported_total is None:
        return {"result": "others"}

    # Extract count of unpaid invoices reported
    count_patterns = [
        re.compile(r"\b(?:number|count)\s+of\s+unpaid\s+invoices\s*[:\-]?\s*(\d+)", re.IGNORECASE),
        re.compile(r"\bunpaid\s+invoices\s*[:\-]?\s*(\d+)\b", re.IGNORECASE),
        re.compile(r"\bcount\s+of\s+invoices\s+.*?unpaid\s*[:\-]?\s*(\d+)", re.IGNORECASE | re.DOTALL),
        re.compile(r"\bunpaid\s+count\s*[:\-]?\s*(\d+)\b", re.IGNORECASE)
    ]
    reported_unpaid = None
    for cp in count_patterns:
        mc = cp.search(text)
        if mc:
            try:
                reported_unpaid = int(mc.group(1))
            except Exception:
                reported_unpaid = None
            if reported_unpaid is not None:
                break
    if reported_unpaid is None:
        return {"result": "others"}

    # Final validations of computed vs reported
    if abs(float(outstanding_total) - float(reported_total)) > 0.01:
        return {"result": "others"}
    if int(unpaid_count) != int(reported_unpaid):
        return {"result": "others"}

    return {"result": "complete"}

def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    import re

    # Helper: run a read-only query safely; return empty list on any DB error
    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cur = conn.cursor()
            cur.execute(query, params)
            rows = cur.fetchall()
            conn.close()
            return rows
        except Exception:
            return []

    expected_title = "How to fix TypeError: unsupported operand type(s) for +: int and str in Python?"
    required_tags = {"python", "typeerror", "python-3.x"}
    current_user_id = 1

    # 1) Collect initial question IDs with the exact title
    initial_q_rows = safe_query(
        initial_db_path,
        "SELECT id FROM questions WHERE title = ?",
        (expected_title,)
    )
    initial_ids = {row[0] for row in initial_q_rows if isinstance(row, tuple) and len(row) > 0 and isinstance(row[0], int)}

    # 2) Get final questions with the exact title
    final_q_rows = safe_query(
        final_db_path,
        "SELECT id, owner_user_id, body FROM questions WHERE title = ?",
        (expected_title,)
    )

    if not final_q_rows:
        return {"result": "others"}

    # Precompile regex patterns
    py311_re = re.compile(r"python\s*3\.11", re.IGNORECASE)
    code_re = re.compile(r"(?i)total\s*=\s*5\s*\+\s*'3'")

    # Helper to get tag names for a question id in final DB
    def get_tag_names_for_question(qid: int) -> set:
        rows = safe_query(
            final_db_path,
            "SELECT t.name FROM question_tags qt JOIN tags t ON t.id = qt.tag_id WHERE qt.question_id = ?",
            (qid,)
        )
        names = set()
        for r in rows:
            if isinstance(r, tuple) and len(r) > 0 and isinstance(r[0], str):
                names.add(r[0].strip().lower())
        return names

    # 3) Validate existence of a new qualifying question
    for row in final_q_rows:
        if not (isinstance(row, tuple) and len(row) >= 3):
            continue
        qid, owner_user_id, body = row[0], row[1], row[2]
        # Must be a new question (id not present in initial set)
        if not isinstance(qid, int) or qid in initial_ids:
            continue
        # Must be owned by current_user
        if owner_user_id != current_user_id:
            continue
        # Body checks
        if not isinstance(body, str) or body.strip() == "":
            continue
        if py311_re.search(body) is None:
            continue
        if code_re.search(body) is None:
            continue
        # Tag checks: required tags must be included
        tag_names = get_tag_names_for_question(qid)
        if not tag_names:
            continue
        if not required_tags.issubset(tag_names):
            continue
        # All checks passed for this new question
        return {"result": "complete"}

    return {"result": "others"}

"""Shared helpers: faithfully rebuild each scenario's INITIAL database from
gen_db.jsonl + gen_sample.jsonl (mirroring awm.core.db.create_sqlite_database and
awm.core.sample.execute_sample_data), then replay verifier rules on episode
databases using the same execution path as awm.core.verify.

Used only for diagnosing and repairing verifier-rule defects in place.
"""
import copy
import inspect
import json
import os
import re
import sqlite3
import tempfile
from pathlib import Path

DATA_ROOT = Path(__file__).resolve().parents[1] / "data" / "AgentWorldModel-1K"
DB_FILE = DATA_ROOT / "gen_db.jsonl"
SAMPLE_FILE = DATA_ROOT / "gen_sample.jsonl"
VERIFIER_FILE = DATA_ROOT / "gen_verifier.pure_code.jsonl"


def normalize_scenario_name(scenario: str) -> str:
    s = scenario.lower()
    s = re.sub(r"[^a-z0-9_]", "_", s)
    s = re.sub(r"_+", "_", s).strip("_").strip()
    return s


def tools_jsonl_load(path):
    with open(path, "r") as f:
        return [json.loads(line) for line in f if line.strip()]


def find_scenario_entry(data, scenario, task_idx=None):
    scenario_norm = normalize_scenario_name(scenario)
    for entry in data:
        if normalize_scenario_name(entry.get("scenario", "")) != scenario_norm:
            continue
        if task_idx is not None and entry.get("task_idx") != task_idx:
            continue
        return entry
    return None


def create_sqlite_database(db_schema: dict, db_path: str):
    if os.path.exists(db_path):
        os.remove(db_path)
    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()
    errors = []
    for table in db_schema.get("tables", []):
        table_name = table.get("name", "unknown")
        try:
            cursor.execute(table["ddl"])
            for index_sql in table.get("indexes", []):
                cursor.execute(index_sql)
            for example_sql in table.get("examples", []):
                cursor.execute(example_sql)
        except Exception as e:
            errors.append(f"Table {table_name}: {str(e)[:300]}")
    conn.commit()
    conn.close()
    return errors


def execute_sample_data(db_path: str, sample_data: dict):
    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()
    cursor.execute("PRAGMA foreign_keys = ON;")
    failures = []
    try:
        for table_data in sample_data.get("tables", []):
            table_name = table_data.get("table_name", "unknown")
            for stmt in table_data.get("insert_statements", []):
                try:
                    cursor.execute(stmt)
                except sqlite3.Error as e:
                    failures.append(f"{table_name}: {str(e)[:200]} :: {stmt[:200]}")
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()
    return failures


def build_initial_db(scenario: str, out_dir: str) -> tuple[str, list]:
    """Rebuild the initial DB for a scenario exactly like the AWM runtime reset."""
    db_rows = tools_jsonl_load(DB_FILE)
    sample_rows = tools_jsonl_load(SAMPLE_FILE)
    schema_item = find_scenario_entry(db_rows, scenario)
    sample_item = find_scenario_entry(sample_rows, scenario)
    if not schema_item or not sample_item:
        raise ValueError(f"missing db/sample for scenario {scenario}")
    os.makedirs(out_dir, exist_ok=True)
    db_path = os.path.join(out_dir, normalize_scenario_name(scenario) + ".db")
    errors = create_sqlite_database(schema_item["db_schema"], db_path)
    failures = execute_sample_data(db_path, sample_item["sample_data"])
    return db_path, errors + failures


def _call_verifier_func(verify_func, initial_db_path, final_db_path, final_answer=None):
    sig = inspect.signature(verify_func)
    params = sig.parameters
    kwargs = {}
    if "initial_db_path" in params:
        kwargs["initial_db_path"] = initial_db_path
    if "final_db_path" in params:
        kwargs["final_db_path"] = final_db_path
    if "final_answer" in params:
        kwargs["final_answer"] = final_answer or ""
    if not kwargs and len(params) >= 2:
        args = [initial_db_path, final_db_path]
        if len(params) >= 3:
            args.append(final_answer or "")
        return verify_func(*args)
    return verify_func(**kwargs)


def execute_code_verifier(verifier_code, function_name, initial_db_path, final_db_path, final_answer=None):
    """Identical semantics to awm.core.verify.execute_code_verifier."""
    if not os.path.exists(initial_db_path):
        return {"result": "others", "execution_status": "error", "error_message": f"Initial DB not found: {initial_db_path}"}
    if not os.path.exists(final_db_path):
        return {"result": "others", "execution_status": "error", "error_message": f"Final DB not found: {final_db_path}"}

    original_modes = {}
    for path in [initial_db_path, final_db_path]:
        try:
            original_modes[path] = os.stat(path).st_mode
            os.chmod(path, 0o444)
        except Exception:
            pass

    try:
        namespace = {
            "sqlite3": sqlite3,
            "json": json,
            "os": os,
            "re": re,
            "__builtins__": __builtins__,
        }
        exec(verifier_code, namespace)
        verify_func = namespace.get(function_name)
        if not verify_func:
            return {"result": "others", "execution_status": "error", "error_message": f"Function '{function_name}' not found"}
        result = _call_verifier_func(verify_func, initial_db_path, final_db_path, final_answer)
        if not isinstance(result, dict) or "result" not in result:
            return {"result": "others", "execution_status": "error", "error_message": f"Invalid return format: {type(result).__name__}"}
        result_value = result.get("result", "others")
        if result_value not in ("complete", "others"):
            result_value = "others"
        return {"result": result_value, "execution_status": "success", "raw_result": result}
    except Exception as e:
        return {"result": "others", "execution_status": "error", "error_message": f"Execution error: {e}"}
    finally:
        for path, mode in original_modes.items():
            try:
                os.chmod(path, mode)
            except Exception:
                pass


def verifier_function_name(verifier_entry):
    """Mirrors awm.core.verify.run_verifier function-name selection for code mode."""
    code = verifier_entry.get("verification", {}).get("code", "")
    func_name = "verify_task_completion"
    for line in code.split("\n"):
        line = line.strip()
        if line.startswith("def verify_") and "(" in line:
            func_name = line.split("(")[0].replace("def ", "").strip()
            break
    return func_name


def run_rule(verifier_entry, initial_db_path, final_db_path, final_answer=None):
    code = verifier_entry.get("verification", {}).get("code", "")
    if not code or not isinstance(code, str) or len(code.strip()) < 10:
        return {"result": "others", "execution_status": "error", "error_message": "No valid verifier code found"}
    return execute_code_verifier(code, verifier_function_name(verifier_entry),
                                 initial_db_path, final_db_path, final_answer)


def load_all():
    db_rows = tools_jsonl_load(DB_FILE)
    sample_rows = tools_jsonl_load(SAMPLE_FILE)
    verifier_rows = tools_jsonl_load(VERIFIER_FILE)
    tasks_rows = tools_jsonl_load(DATA_ROOT / "gen_tasks.jsonl")
    return db_rows, sample_rows, verifier_rows, tasks_rows

