        SELECT user_id FROM channel_subscriptions
        WHERE channel_id = ? AND status = 'active'
          AND start_at <= ? AND (end_at IS NULL OR end_at >= ?)
        GROUP BY user_id
        """,
        (channel_id, window_start, window_end)
    )
    if len(subs_rows) != 1:
        # Ambiguous which viewer; cannot be 100% certain
        return {"result": "others"}
    viewer_user_id = subs_rows[0][0]

    # 3) Get events in date window (any channel, per task wording)
    ev_rows = safe_query(
        final_db_path,
        "SELECT id, start_time, end_time FROM events WHERE start_time BETWEEN ? AND ? ORDER BY id",
        (window_start, window_end)
    )
    if not ev_rows:
        return {"result": "others"}
    event_ids_in_window = [r[0] for r in ev_rows]

    # 4) Compute expected valid passes for this viewer overlapping each event time and with valid statuses
    ap_rows = safe_query(
        final_db_path,
        """
        SELECT ap.id, ap.event_id, ap.access_type, ap.status, ap.valid_from, ap.valid_until
        FROM access_passes ap
        JOIN events e ON e.id = ap.event_id
        WHERE ap.user_id = ?
          AND e.start_time BETWEEN ? AND ?
          AND ap.status IN ('active','scheduled')
          AND ap.valid_until >= e.start_time
          AND ap.valid_from <= e.end_time
        ORDER BY ap.event_id, ap.id
        """,
        (viewer_user_id, window_start, window_end)
    )
    if not ap_rows:
        return {"result": "others"}

    expected_map: dict[int, set[int]] = {}
    for pid, eid, atype, status, vf, vu in ap_rows:
        expected_map.setdefault(eid, set()).add(int(pid))

    # We expect at least some passes; otherwise cannot verify
    if not expected_map:
        return {"result": "others"}

    # 5) Parse final_answer and validate grouping and pass IDs
    if not isinstance(final_answer, str) or not final_answer.strip():
        return {"result": "others"}

    parsed_map = parse_event_pass_map(final_answer)
    if not parsed_map:
        return {"result": "others"}

    # Only consider event IDs that are in the date window (ignore any other mentions)
    # Filter both maps to intersection with event_ids_in_window
    expected_keys = set(expected_map.keys())
    # Remove any entries for events with zero passes (should not exist in expected_map)
    parsed_filtered = {eid: set(pids) for eid, pids in parsed_map.items() if eid in event_ids_in_window}

    # Strict match: keys must match exactly, and pass-id sets must match exactly per event
    if set(parsed_filtered.keys()) != expected_keys:
        return {"result": "others"}
    for eid in expected_keys:
        exp_set = expected_map.get(eid, set())
        got_set = parsed_filtered.get(eid, set())
        if got_set != exp_set:
            return {"result": "others"}

    # Additional safety: ensure there are no extra event groups with IDs in window outside expected keys
    extra_in_answer = [eid for eid in parsed_map.keys() if (eid in event_ids_in_window and eid not in expected_keys)]
    if extra_in_answer:
        return {"result": "others"}

    return {"result": "complete"}

def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    import re

    # Safe DB query helper
    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            conn.row_factory = sqlite3.Row
            cur = conn.cursor()
            cur.execute(query, params)
            rows = cur.fetchall()
            conn.close()
            return rows
        except Exception:
            return []

    # Parse YYYY-MM-DD safely into (y, m, d); return None on failure
    def parse_date_ymd(s: str):
        if not isinstance(s, str):
            return None
        m = re.fullmatch(r"(\d{4})-(\d{2})-(\d{2})", s.strip())
        if not m:
            return None
        y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
        if mo < 1 or mo > 12 or d < 1 or d > 31:
            return None
        return (y, mo, d)

    # Full months between two dates inclusive of month boundaries; floor months elapsed
    def months_between(start_ymd, end_ymd):
        if not start_ymd or not end_ymd:
            return None
        y1, m1, d1 = start_ymd
        y2, m2, d2 = end_ymd
        base = (y2 - y1) * 12 + (m2 - m1)
        if d2 < d1:
            base -= 1
        return base

    # Extract a money-like value as float from text segment; returns None if not found/invalid
    def extract_money_value(seg: str):
        if not isinstance(seg, str):
            return None
        m = re.search(r"\$?\s*([0-9][\d,]*(?:\.\d+)?)", seg)
        if not m:
            return None
        val_str = m.group(1).replace(",", "").strip()
        if not re.fullmatch(r"\d+(?:\.\d+)?", val_str):
            return None
        try:
            return float(val_str)
        except Exception:
            return None

    # Extract an average months value near a type mention
    def extract_avg_months(seg: str):
        if not isinstance(seg, str):
            return None
        m = re.search(r"(?:avg|average)[^0-9-]*([0-9]+(?:\.[0-9]+)?)\s*month", seg, flags=re.IGNORECASE)
        if not m:
            return None
        s = m.group(1)
        if not re.fullmatch(r"\d+(?:\.\d+)?", s):
            return None
        try:
            return float(s)
        except Exception:
            return None

    # Try to find revenue and avg months for a given asset type name in the final_answer
    def find_type_metrics(text: str, type_name: str):
        if not isinstance(text, str) or not isinstance(type_name, str):
            return (None, None)
        name_pat = re.escape(type_name)
        # Primary: regex over entire text allowing arbitrary formatting
        pat = rf"{name_pat}.*?(\$?\s*[0-9][\d,]*(?:\\.\d+)?).*?(?:avg|average)[^0-9-]*([0-9]+(?:\\.[0-9]+)?)\\s*month"
        m = re.search(pat, text, flags=re.IGNORECASE | re.DOTALL)
        if m:
            rev = extract_money_value(m.group(1))
            try:
                avgm = float(m.group(2))
            except Exception:
                avgm = None
            return (rev, avgm)
        # Fallback: scan nearby lines
        lines = text.splitlines()
        for i, line in enumerate(lines):
            if type_name.lower() in line.lower():
                seg = line
                if i + 1 < len(lines):
                    seg += " " + lines[i + 1]
                if i + 2 < len(lines):
                    seg += " " + lines[i + 2]
                rev = None
                # Prefer revenue preceded by the word revenue
                mrev = re.search(r"revenue[^0-9$]*([\$]?\s*[0-9][\d,]*(?:\.\d+)?)", seg, flags=re.IGNORECASE)
                if mrev:
                    rev = extract_money_value(mrev.group(1))
                if rev is None:
                    rev = extract_money_value(seg)
                avgm = extract_avg_months(seg)
                if rev is not None and avgm is not None:
                    return (rev, avgm)
        return (None, None)

    # Choose DB to read from (prefer final)
    db_path = final_db_path if final_db_path else initial_db_path
    if not db_path:
        return {"result": "others"}

    # Load asset types
    at_rows = safe_query(db_path, "SELECT id, name FROM asset_types", ())
    type_id_to_name = {row["id"]: row["name"] for row in at_rows} if at_rows else {}
    if not type_id_to_name:
        return {"result": "others"}

    # Load assets
    a_rows = safe_query(db_path, "SELECT id, asset_type_id, asset_tag, purchase_date FROM assets", ())
    if not a_rows:
        return {"result": "others"}

    # Compute ages as of 2025-12-31
    end_ymd = parse_date_ymd("2025-12-31")
    if not end_ymd:
        return {"result": "others"}

    assets_info = []
    for r in a_rows:
        pid = r["id"]
        tid = r["asset_type_id"]
        tag = r["asset_tag"] if isinstance(r["asset_tag"], str) else ""
        pdate = r["purchase_date"] if isinstance(r["purchase_date"], str) else None
        symd = parse_date_ymd(pdate) if pdate else None
        mths = months_between(symd, end_ymd) if symd else None
        assets_info.append({"id": pid, "type_id": tid, "tag": tag, "purchase_date": pdate, "age_months": mths})

    # Qualifying assets: age >= 60 months
    qualifying = [a for a in assets_info if isinstance(a.get("age_months"), int) and a["age_months"] >= 60]
    if not qualifying:
        return {"result": "others"}

    qual_ids = [a["id"] for a in qualifying]
    qual_tags = [a["tag"] for a in qualifying if a.get("tag")] 

    # Revenue by asset (restricted to qualifying assets)
    if qual_ids:
        # Build parameter placeholders safely
        ph = ",".join(["?"] * len(qual_ids))
        r_rows = safe_query(db_path, f"SELECT r.asset_id, r.revenue_amount FROM revenue_by_asset r WHERE r.asset_id IN ({ph})", tuple(qual_ids))
    else:
        r_rows = []

    revenue_by_asset = {}
    for r in r_rows:
        aid = r["asset_id"]
        amt = r["revenue_amount"] if r["revenue_amount"] is not None else 0.0
        if not isinstance(amt, (int, float)):
            continue
        revenue_by_asset[aid] = revenue_by_asset.get(aid, 0.0) + float(amt)

    # Aggregate by type for qualifying assets
    type_to_revenue = {}
    type_to_ages = {}
    for a in qualifying:
        tid = a["type_id"]
        type_to_ages.setdefault(tid, []).append(a["age_months"])
        rev = float(revenue_by_asset.get(a["id"], 0.0))
        type_to_revenue[tid] = type_to_revenue.get(tid, 0.0) + rev

    # Build top 5 list by revenue desc
    type_summaries = []
    for tid, ages in type_to_ages.items():
        name = type_id_to_name.get(tid, str(tid))
        if not ages or not name:
            continue
        avg_age = sum(ages) / len(ages)
        total_rev = float(type_to_revenue.get(tid, 0.0))
        type_summaries.append({"type_id": tid, "name": name, "total_revenue": total_rev, "avg_age_months": avg_age})

    if not type_summaries:
        return {"result": "others"}

    # Sort by revenue desc, then name for determinism
    type_summaries.sort(key=lambda x: (-x["total_revenue"], x["name"]))
    top5 = type_summaries[:5]

    # Begin validating final_answer text
    if not isinstance(final_answer, str) or not final_answer.strip():
        return {"result": "others"}
    text = final_answer

    # Must mention cutoff date and 5-year (or 60 months) condition
    if "2025-12-31" not in text:
        return {"result": "others"}
    cond_pat = re.compile(r"(older\s*than\s*5\s*years|over\s*5\s*years|>=\s*5\s*years|at\s*least\s*5\s*years|60\s*months)", re.IGNORECASE)
    if not cond_pat.search(text):
        return {"result": "others"}

    # Must contain both section cues
    if not re.search(r"asset[\s_-]*age[\s_-]*report", text, flags=re.IGNORECASE):
        return {"result": "others"}
    if not re.search(r"revenue[\s_-]*by[\s_-]*asset[\s_-]*type", text, flags=re.IGNORECASE):
        return {"result": "others"}

    # Ensure all qualifying asset tags are present
    for tag in qual_tags:
        if not tag:
            return {"result": "others"}
        if re.search(re.escape(tag), text, flags=re.IGNORECASE) is None:
            return {"result": "others"}

    # Validate each top 5 asset type has correct total revenue and average age months
    for entry in top5:
        tname = entry["name"]
        expected_rev = float(entry["total_revenue"])
        expected_avg = float(entry["avg_age_months"])
        found_rev, found_avg = find_type_metrics(text, tname)
        # Require both metrics found
        if found_rev is None or found_avg is None:
            return {"result": "others"}
        # Compare with tolerant formatting; exact numeric equality within small tolerance
        if not isinstance(found_rev, (int, float)) or not isinstance(found_avg, (int, float)):
            return {"result": "others"}
        if abs(found_rev - expected_rev) > 0.5:
            return {"result": "others"}
        if abs(found_avg - expected_avg) > 0.5:
            return {"result": "others"}

    return {"result": "complete"}

"""Shared helpers: faithfully rebuild each scenario's INITIAL database from
gen_db.jsonl + gen_sample.jsonl (mirroring awm.core.db.create_sqlite_database and
awm.core.sample.execute_sample_data), then replay verifier rules on episode
databases using the same execution path as awm.core.verify.

Used only for diagnosing and repairing verifier-rule defects in place.
"""
import copy
import inspect
import json
import os
import re
import sqlite3
import tempfile
from pathlib import Path

DATA_ROOT = Path(__file__).resolve().parents[1] / "data" / "AgentWorldModel-1K"
DB_FILE = DATA_ROOT / "gen_db.jsonl"
SAMPLE_FILE = DATA_ROOT / "gen_sample.jsonl"
VERIFIER_FILE = DATA_ROOT / "gen_verifier.pure_code.jsonl"


def normalize_scenario_name(scenario: str) -> str:
    s = scenario.lower()
    s = re.sub(r"[^a-z0-9_]", "_", s)
    s = re.sub(r"_+", "_", s).strip("_").strip()
    return s


def tools_jsonl_load(path):
    with open(path, "r") as f:
        return [json.loads(line) for line in f if line.strip()]


def find_scenario_entry(data, scenario, task_idx=None):
    scenario_norm = normalize_scenario_name(scenario)
    for entry in data:
        if normalize_scenario_name(entry.get("scenario", "")) != scenario_norm:
            continue
        if task_idx is not None and entry.get("task_idx") != task_idx:
            continue
        return entry
    return None


def create_sqlite_database(db_schema: dict, db_path: str):
    if os.path.exists(db_path):
        os.remove(db_path)
    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()
    errors = []
    for table in db_schema.get("tables", []):
        table_name = table.get("name", "unknown")
        try:
            cursor.execute(table["ddl"])
            for index_sql in table.get("indexes", []):
                cursor.execute(index_sql)
            for example_sql in table.get("examples", []):
                cursor.execute(example_sql)
        except Exception as e:
            errors.append(f"Table {table_name}: {str(e)[:300]}")
    conn.commit()
    conn.close()
    return errors


def execute_sample_data(db_path: str, sample_data: dict):
    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()
    cursor.execute("PRAGMA foreign_keys = ON;")
    failures = []
    try:
        for table_data in sample_data.get("tables", []):
            table_name = table_data.get("table_name", "unknown")
            for stmt in table_data.get("insert_statements", []):
                try:
                    cursor.execute(stmt)
                except sqlite3.Error as e:
                    failures.append(f"{table_name}: {str(e)[:200]} :: {stmt[:200]}")
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()
    return failures


def build_initial_db(scenario: str, out_dir: str) -> tuple[str, list]:
    """Rebuild the initial DB for a scenario exactly like the AWM runtime reset."""
    db_rows = tools_jsonl_load(DB_FILE)
    sample_rows = tools_jsonl_load(SAMPLE_FILE)
    schema_item = find_scenario_entry(db_rows, scenario)
    sample_item = find_scenario_entry(sample_rows, scenario)
    if not schema_item or not sample_item:
        raise ValueError(f"missing db/sample for scenario {scenario}")
    os.makedirs(out_dir, exist_ok=True)
    db_path = os.path.join(out_dir, normalize_scenario_name(scenario) + ".db")
    errors = create_sqlite_database(schema_item["db_schema"], db_path)
    failures = execute_sample_data(db_path, sample_item["sample_data"])
    return db_path, errors + failures


def _call_verifier_func(verify_func, initial_db_path, final_db_path, final_answer=None):
    sig = inspect.signature(verify_func)
    params = sig.parameters
    kwargs = {}
    if "initial_db_path" in params:
        kwargs["initial_db_path"] = initial_db_path
    if "final_db_path" in params:
        kwargs["final_db_path"] = final_db_path
    if "final_answer" in params:
        kwargs["final_answer"] = final_answer or ""
    if not kwargs and len(params) >= 2:
        args = [initial_db_path, final_db_path]
        if len(params) >= 3:
            args.append(final_answer or "")
        return verify_func(*args)
    return verify_func(**kwargs)


def execute_code_verifier(verifier_code, function_name, initial_db_path, final_db_path, final_answer=None):
    """Identical semantics to awm.core.verify.execute_code_verifier."""
    if not os.path.exists(initial_db_path):
        return {"result": "others", "execution_status": "error", "error_message": f"Initial DB not found: {initial_db_path}"}
    if not os.path.exists(final_db_path):
        return {"result": "others", "execution_status": "error", "error_message": f"Final DB not found: {final_db_path}"}

    original_modes = {}
    for path in [initial_db_path, final_db_path]:
        try:
            original_modes[path] = os.stat(path).st_mode
            os.chmod(path, 0o444)
        except Exception:
            pass

    try:
        namespace = {
            "sqlite3": sqlite3,
            "json": json,
            "os": os,
            "re": re,
            "__builtins__": __builtins__,
        }
        exec(verifier_code, namespace)
        verify_func = namespace.get(function_name)
        if not verify_func:
            return {"result": "others", "execution_status": "error", "error_message": f"Function '{function_name}' not found"}
        result = _call_verifier_func(verify_func, initial_db_path, final_db_path, final_answer)
        if not isinstance(result, dict) or "result" not in result:
            return {"result": "others", "execution_status": "error", "error_message": f"Invalid return format: {type(result).__name__}"}
        result_value = result.get("result", "others")
        if result_value not in ("complete", "others"):
            result_value = "others"
        return {"result": result_value, "execution_status": "success", "raw_result": result}
    except Exception as e:
        return {"result": "others", "execution_status": "error", "error_message": f"Execution error: {e}"}
    finally:
        for path, mode in original_modes.items():
            try:
                os.chmod(path, mode)
            except Exception:
                pass


def verifier_function_name(verifier_entry):
    """Mirrors awm.core.verify.run_verifier function-name selection for code mode."""
    code = verifier_entry.get("verification", {}).get("code", "")
    func_name = "verify_task_completion"
    for line in code.split("\n"):
        line = line.strip()
        if line.startswith("def verify_") and "(" in line:
            func_name = line.split("(")[0].replace("def ", "").strip()
            break
    return func_name


def run_rule(verifier_entry, initial_db_path, final_db_path, final_answer=None):
    code = verifier_entry.get("verification", {}).get("code", "")
    if not code or not isinstance(code, str) or len(code.strip()) < 10:
        return {"result": "others", "execution_status": "error", "error_message": "No valid verifier code found"}
    return execute_code_verifier(code, verifier_function_name(verifier_entry),
                                 initial_db_path, final_db_path, final_answer)


def load_all():
    db_rows = tools_jsonl_load(DB_FILE)
    sample_rows = tools_jsonl_load(SAMPLE_FILE)
    verifier_rows = tools_jsonl_load(VERIFIER_FILE)
    tasks_rows = tools_jsonl_load(DATA_ROOT / "gen_tasks.jsonl")
    return db_rows, sample_rows, verifier_rows, tasks_rows

def _awm_orig_verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None, _awm_ev=None) -> dict:
    def _awm_probe_final(query, *params, **kw):
        """AWM repair: run the rule's own final-DB query and compare against the initial DB."""
        try:
            _awm_rows = safe_query(final_db_path, query, *params, **kw)
        except Exception:
            return []
        _awm_diff = True  # cannot compare -> assume a difference (stay complete)
        try:
            if isinstance(_awm_rows, (list, tuple)):
                _awm_init = safe_query(initial_db_path, query, *params, **kw)
                _awm_diff = (list(_awm_rows) != list(_awm_init))
        except Exception:
            _awm_diff = True
        try:
            _awm_ev.append(_awm_diff)
        except Exception:
            pass
        return _awm_rows
    import sqlite3
    import re

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    # Check if the auction_event exists with correct attributes
    event_query = """
        SELECT id, title, start_date, end_date, category_scope, 
               buyer_premium_percentage, payment_deadline_days, shipping_policies
        FROM auction_events
        WHERE title = ?
    """

    event_title = "Signed Movie Memorabilia – Spring Showcase"
    events = _awm_probe_final(event_query, (event_title,))

    # AWM repair: the seeded data already contains an auction_event
    # with this exact title (lots 901/902/910 already assigned to it),
    # so for a genuine completion that creates its own event and
    # reassigns the lots, the events[0] binding below would select the
    # seeded row and the lots check would test the wrong
    # auction_event_id. Prefer the event the episode itself created;
    # fall back to the seeded row when none was created (in-place
    # edits of the seeded event still verify; the newness guard
    # rejects a do-nothing episode).
    initial_event_ids = set(row[0] for row in
        safe_query(initial_db_path, event_query, (event_title,)))
    episode_events = [e for e in events if e[0] not in initial_event_ids]
    if episode_events:
        events = episode_events

    if not events:
        return {"result": "others"}

    # Get the event details
    event_id, title, start_date, end_date, category_scope, buyer_premium, payment_days, shipping_policies = events[0]

    # Verify all event attributes
    # Check dates - SQLite stores as '2025-03-01 16:00:00' format
    expected_start = "2025-03-01 16:00:00"
    expected_end = "2025-03-08 16:00:00"

    if start_date != expected_start:
        return {"result": "others"}

    if end_date != expected_end:
        return {"result": "others"}

    # Check category_scope
    if category_scope != "memorabilia":
        return {"result": "others"}

    # Check buyer_premium_percentage (allow for float comparison)
    if abs(buyer_premium - 17.0) > 0.01:
        return {"result": "others"}

    # Check payment_deadline_days
    if payment_days != 7:
        return {"result": "others"}

    # Check shipping_policies contains separate rules for posters, props, and scripts
    if not shipping_policies:
        return {"result": "others"}

    shipping_lower = shipping_policies.lower()
    has_poster_rules = "poster" in shipping_lower
    has_prop_rules = "prop" in shipping_lower
    has_script_rules = "script" in shipping_lower

    if not (has_poster_rules and has_prop_rules and has_script_rules):
        return {"result": "others"}

    # Verify lots 901, 902, 910 are assigned to this event
    lot_ids = [901, 902, 910]
    lots_query = "SELECT id, auction_event_id FROM lots WHERE id IN (?, ?, ?)"
    lots = _awm_probe_final(lots_query, tuple(lot_ids))

    if len(lots) != 3:
        return {"result": "others"}

    # Check that all three lots are assigned to the correct event
    for lot_id, auction_event_id in lots:
        if auction_event_id != event_id:
            return {"result": "others"}

    # All checks passed
    return {"result": "complete"}

# --- AWM newness guard wrapper (appended by in-place repair; see report.md) ---
def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    _awm_ev_local = []
    _awm_result = _awm_orig_verify_task_completion(initial_db_path=initial_db_path, final_db_path=final_db_path, final_answer=final_answer, _awm_ev=_awm_ev_local)
    if isinstance(_awm_result, dict) and _awm_result.get("result") == "complete":
        if not any(_awm_ev_local):
