    return _awm_result

def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    import re
    from datetime import datetime, timedelta, time, timezone
    try:
        from zoneinfo import ZoneInfo
    except Exception:
        ZoneInfo = None

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            rows = cursor.fetchall()
            conn.close()
            return rows
        except Exception:
            return []

    def parse_utc_dt(s: str):
        if not s or not isinstance(s, str):
            return None
        s = s.strip()
        fmt = "%Y-%m-%d %H:%M:%S"
        try:
            dt = datetime.strptime(s, fmt)
        except Exception:
            # try trimming microseconds if present
            try:
                # handle cases like 'YYYY-MM-DD HH:MM:SS.sss'
                base = s.split(".")[0]
                dt = datetime.strptime(base, fmt)
            except Exception:
                return None
        return dt.replace(tzinfo=timezone.utc)

    def compute_next_friday_2030_utc(created_at_utc: datetime, tz_name: str):
        if created_at_utc is None:
            return None
        if not tz_name or not isinstance(tz_name, str):
            tz_name = "UTC"
        if ZoneInfo is None:
            return None
        try:
            tz = ZoneInfo(tz_name)
        except Exception:
            return None
        local_dt = created_at_utc.astimezone(tz)
        weekday = local_dt.weekday()  # Mon=0 .. Sun=6
        target_weekday = 4  # Friday
        days_ahead = (target_weekday - weekday) % 7
        target_local_time = time(20, 30, 0)
        if days_ahead == 0 and (local_dt.time() >= target_local_time):
            days_ahead = 7
        target_date = (local_dt.date() + timedelta(days=days_ahead))
        target_local_dt = datetime.combine(target_date, target_local_time, tzinfo=tz)
        return target_local_dt.astimezone(timezone.utc)

    # 1) Resolve current user and timezone from final DB
    user_rows = safe_query(final_db_path, "SELECT id, timezone FROM users WHERE username = ? LIMIT 1", ("current_user",))
    if not user_rows:
        # Fallback: try user id 1
        user_rows = safe_query(final_db_path, "SELECT id, timezone FROM users WHERE id = 1 LIMIT 1", ())
    if not user_rows:
        return {"result": "others"}
    current_user_id, current_user_tz = user_rows[0]
    if not current_user_tz or not isinstance(current_user_tz, str) or len(current_user_tz.strip()) == 0:
        current_user_tz = "UTC"

    # 2) Initial max room id to detect new rooms
    init_max_rows = safe_query(initial_db_path, "SELECT COALESCE(MAX(id), 0) FROM rooms", ())
    if not init_max_rows or init_max_rows[0][0] is None:
        init_max_room_id = 0
    else:
        init_max_room_id = int(init_max_rows[0][0])

    # 3) Ensure media items exist in final DB for given external IDs
    target_ext_ids = ("tt0078748", "tt0081505")
    mi_rows = safe_query(final_db_path, "SELECT id, external_id FROM media_items WHERE external_id IN (?, ?)", target_ext_ids)
    ext_to_id = {row[1]: row[0] for row in mi_rows if row[1] in target_ext_ids}
    if len(ext_to_id) != 2:
        return {"result": "others"}
    req_media_ids = {ext_to_id["tt0078748"], ext_to_id["tt0081505"]}

    # 4) Find candidate new rooms created by current user with exact specified attributes
    room_rows = safe_query(
        final_db_path,
        """
        SELECT id, owner_user_id, title, description, visibility, access_mode, max_participants, created_at
        FROM rooms
        WHERE owner_user_id = ?
          AND title = ?
          AND description = ?
          AND visibility = 'public'
          AND access_mode = 'public'
          AND max_participants = 12
          AND id > ?
        """,
        (current_user_id, "Friday Horror Night", "Classic horror double feature", init_max_room_id),
    )
    if not room_rows:
        return {"result": "others"}

    valid_room_candidates = []

    for r in room_rows:
        room_id = r[0]
        # 5) Verify both media items are linked to this room
        rmi_rows = safe_query(final_db_path, "SELECT media_item_id FROM room_media_items WHERE room_id = ?", (room_id,))
        linked_ids = {row[0] for row in rmi_rows if row and row[0] is not None}
        has_required_links = req_media_ids.issubset(linked_ids)
        if not has_required_links:
            continue

        # 6) Verify a scheduled room_session exists for this room at next Friday 8:30 PM local time, computed from session.created_at
        sess_rows = safe_query(
            final_db_path,
            "SELECT id, start_time_utc, status, host_user_id, created_at FROM room_sessions WHERE room_id = ? AND status = 'scheduled'",
            (room_id,)
        )
        session_ok = False
        for s in sess_rows:
            sid, start_time_utc_str, status, host_user_id, sess_created_at_str = s
            if status != 'scheduled' or host_user_id != current_user_id:
                continue
            start_utc = parse_utc_dt(start_time_utc_str)
            created_utc = parse_utc_dt(sess_created_at_str)
            if start_utc is None or created_utc is None:
                continue
            expected_start_utc = compute_next_friday_2030_utc(created_utc, current_user_tz)
            if expected_start_utc is None:
                continue
            # Compare to the second
            if int(start_utc.timestamp()) == int(expected_start_utc.timestamp()):
                session_ok = True
                break
        if session_ok:
            valid_room_candidates.append(room_id)

    # There must be exactly one unambiguous room that satisfies all criteria
    if len(valid_room_candidates) == 1:
        return {"result": "complete"}

    return {"result": "others"}

def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    import re
    from datetime import datetime, timezone, timedelta, time
    from zoneinfo import ZoneInfo

    # Helper to safely query database (read-only)
    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            conn.row_factory = sqlite3.Row
            cur = conn.cursor()
            cur.execute(query, params)
            rows = cur.fetchall()
            conn.close()
            return rows
        except Exception:
            return []

    # Basic validations for room and user
    rooms = safe_query(final_db_path, "SELECT id FROM rooms WHERE title = ?", ("Sunday Sitcom Rewatch",))
    if not rooms or len(rooms) != 1:
        return {"result": "others"}
    room_id = rooms[0]["id"] if "id" in rooms[0].keys() else rooms[0][0]

    users = safe_query(final_db_path, "SELECT id, timezone FROM users WHERE username = ?", ("current_user",))
    if not users or len(users) != 1:
        return {"result": "others"}
    current_user_id = users[0]["id"] if "id" in users[0].keys() else users[0][0]
    user_timezone = users[0]["timezone"] if "timezone" in users[0].keys() else users[0][1] if len(users[0]) > 1 else None
    if not user_timezone:
        return {"result": "others"}

    # Collect initial room_session IDs for the room from the initial DB
    initial_sessions = safe_query(initial_db_path, "SELECT id FROM room_sessions WHERE room_id = ?", (room_id,))
    initial_ids = set()
    for r in initial_sessions:
        if r and len(r) >= 1 and r[0] is not None:
            initial_ids.add(r[0])

    # Final DB: fetch all scheduled sessions for this room
    final_scheduled = safe_query(
        final_db_path,
        """
        SELECT id, room_id, host_user_id, start_time_utc, status,
               initial_playback_position_seconds, initial_playback_status,
               created_at
        FROM room_sessions
        WHERE room_id = ? AND status = 'scheduled'
        """,
        (room_id,)
    )

    if not final_scheduled:
        return {"result": "others"}

    # Determine newly created scheduled sessions (ids not present in initial)
    new_scheduled = []
    for row in final_scheduled:
        rid = row["id"] if "id" in row.keys() else row[0]
        if rid not in initial_ids:
            new_scheduled.append(row)

    # Must be exactly one new scheduled session
    if len(new_scheduled) != 1:
        return {"result": "others"}

    sess = new_scheduled[0]
    # Extract fields safely
    host_user_id = sess["host_user_id"] if "host_user_id" in sess.keys() else None
    start_time_utc_str = sess["start_time_utc"] if "start_time_utc" in sess.keys() else None
    initial_pos = sess["initial_playback_position_seconds"] if "initial_playback_position_seconds" in sess.keys() else None
    initial_status = sess["initial_playback_status"] if "initial_playback_status" in sess.keys() else None
    created_at_str = sess["created_at"] if "created_at" in sess.keys() else None

    # Validate host and playback state
    if host_user_id != current_user_id:
        return {"result": "others"}
    if initial_pos is None or initial_status is None:
        return {"result": "others"}
    # Ensure exact requirements
    try:
        # Prevent non-integer types; but avoid exceptions elsewhere by guarding
        ipos_int = int(initial_pos)
    except Exception:
        return {"result": "others"}
    if ipos_int != 0:
        return {"result": "others"}
    if str(initial_status).lower() != 'paused':
        return {"result": "others"}

    # Validate datetime strings format to avoid exceptions
    dt_pattern = re.compile(r"^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$")
    if not (start_time_utc_str and created_at_str and dt_pattern.match(start_time_utc_str) and dt_pattern.match(created_at_str)):
        return {"result": "others"}

    # Parse datetimes assuming stored as UTC (SQLite CURRENT_TIMESTAMP is UTC)
    # No try-except for logic after regex validation
    start_time_utc = datetime.strptime(start_time_utc_str, "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
    created_at_utc = datetime.strptime(created_at_str, "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)

    # Ensure scheduled time is in the future relative to creation
    if not (start_time_utc > created_at_utc):
        return {"result": "others"}

    # Compute expected 'coming Sunday' 7:00 PM in user's timezone based on created_at
    tz = ZoneInfo(user_timezone)
    created_local = created_at_utc.astimezone(tz)

    # Determine days ahead to the coming Sunday (Monday=0,...,Sunday=6)
    target_hour = 19
    target_minute = 0
    target_second = 0
    weekday_today = created_local.weekday()
    days_ahead = (6 - weekday_today) % 7  # 6 corresponds to Sunday
    # If today is Sunday and time already past/equal 7:00 PM, pick next Sunday
    if days_ahead == 0:
        if (created_local.hour, created_local.minute, created_local.second) >= (target_hour, target_minute, target_second):
            days_ahead = 7
    target_date = created_local.date() + timedelta(days=days_ahead)
    target_local_dt = datetime.combine(target_date, time(target_hour, target_minute, target_second), tz)
    expected_start_utc = target_local_dt.astimezone(timezone.utc)

    # The scheduled time must match exactly the computed expected UTC
    if expected_start_utc != start_time_utc:
        return {"result": "others"}

    # All checks passed
    return {"result": "complete"}

