"""Shared helpers: faithfully rebuild each scenario's INITIAL database from
gen_db.jsonl + gen_sample.jsonl (mirroring awm.core.db.create_sqlite_database and
awm.core.sample.execute_sample_data), then replay verifier rules on episode
databases using the same execution path as awm.core.verify.

Used only for diagnosing and repairing verifier-rule defects in place.
"""
import copy
import inspect
import json
import os
import re
import sqlite3
import tempfile
from pathlib import Path

DATA_ROOT = Path(__file__).resolve().parents[1] / "data" / "AgentWorldModel-1K"
DB_FILE = DATA_ROOT / "gen_db.jsonl"
SAMPLE_FILE = DATA_ROOT / "gen_sample.jsonl"
VERIFIER_FILE = DATA_ROOT / "gen_verifier.pure_code.jsonl"


def normalize_scenario_name(scenario: str) -> str:
    s = scenario.lower()
    s = re.sub(r"[^a-z0-9_]", "_", s)
    s = re.sub(r"_+", "_", s).strip("_").strip()
    return s


def tools_jsonl_load(path):
    with open(path, "r") as f:
        return [json.loads(line) for line in f if line.strip()]


def find_scenario_entry(data, scenario, task_idx=None):
    scenario_norm = normalize_scenario_name(scenario)
    for entry in data:
        if normalize_scenario_name(entry.get("scenario", "")) != scenario_norm:
            continue
        if task_idx is not None and entry.get("task_idx") != task_idx:
            continue
        return entry
    return None


def create_sqlite_database(db_schema: dict, db_path: str):
    if os.path.exists(db_path):
        os.remove(db_path)
    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()
    errors = []
    for table in db_schema.get("tables", []):
        table_name = table.get("name", "unknown")
        try:
            cursor.execute(table["ddl"])
            for index_sql in table.get("indexes", []):
                cursor.execute(index_sql)
            for example_sql in table.get("examples", []):
                cursor.execute(example_sql)
        except Exception as e:
            errors.append(f"Table {table_name}: {str(e)[:300]}")
    conn.commit()
    conn.close()
    return errors


def execute_sample_data(db_path: str, sample_data: dict):
    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()
    cursor.execute("PRAGMA foreign_keys = ON;")
    failures = []
    try:
        for table_data in sample_data.get("tables", []):
            table_name = table_data.get("table_name", "unknown")
            for stmt in table_data.get("insert_statements", []):
                try:
                    cursor.execute(stmt)
                except sqlite3.Error as e:
                    failures.append(f"{table_name}: {str(e)[:200]} :: {stmt[:200]}")
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()
    return failures


def build_initial_db(scenario: str, out_dir: str) -> tuple[str, list]:
    """Rebuild the initial DB for a scenario exactly like the AWM runtime reset."""
    db_rows = tools_jsonl_load(DB_FILE)
    sample_rows = tools_jsonl_load(SAMPLE_FILE)
    schema_item = find_scenario_entry(db_rows, scenario)
    sample_item = find_scenario_entry(sample_rows, scenario)
    if not schema_item or not sample_item:
        raise ValueError(f"missing db/sample for scenario {scenario}")
    os.makedirs(out_dir, exist_ok=True)
    db_path = os.path.join(out_dir, normalize_scenario_name(scenario) + ".db")
    errors = create_sqlite_database(schema_item["db_schema"], db_path)
    failures = execute_sample_data(db_path, sample_item["sample_data"])
    return db_path, errors + failures


def _call_verifier_func(verify_func, initial_db_path, final_db_path, final_answer=None):
    sig = inspect.signature(verify_func)
    params = sig.parameters
    kwargs = {}
    if "initial_db_path" in params:
        kwargs["initial_db_path"] = initial_db_path
    if "final_db_path" in params:
        kwargs["final_db_path"] = final_db_path
    if "final_answer" in params:
        kwargs["final_answer"] = final_answer or ""
    if not kwargs and len(params) >= 2:
        args = [initial_db_path, final_db_path]
        if len(params) >= 3:
            args.append(final_answer or "")
        return verify_func(*args)
    return verify_func(**kwargs)


def execute_code_verifier(verifier_code, function_name, initial_db_path, final_db_path, final_answer=None):
    """Identical semantics to awm.core.verify.execute_code_verifier."""
    if not os.path.exists(initial_db_path):
        return {"result": "others", "execution_status": "error", "error_message": f"Initial DB not found: {initial_db_path}"}
    if not os.path.exists(final_db_path):
        return {"result": "others", "execution_status": "error", "error_message": f"Final DB not found: {final_db_path}"}

    original_modes = {}
    for path in [initial_db_path, final_db_path]:
        try:
            original_modes[path] = os.stat(path).st_mode
            os.chmod(path, 0o444)
        except Exception:
            pass

    try:
        namespace = {
            "sqlite3": sqlite3,
            "json": json,
            "os": os,
            "re": re,
            "__builtins__": __builtins__,
        }
        exec(verifier_code, namespace)
        verify_func = namespace.get(function_name)
        if not verify_func:
            return {"result": "others", "execution_status": "error", "error_message": f"Function '{function_name}' not found"}
        result = _call_verifier_func(verify_func, initial_db_path, final_db_path, final_answer)
        if not isinstance(result, dict) or "result" not in result:
            return {"result": "others", "execution_status": "error", "error_message": f"Invalid return format: {type(result).__name__}"}
        result_value = result.get("result", "others")
        if result_value not in ("complete", "others"):
            result_value = "others"
        return {"result": result_value, "execution_status": "success", "raw_result": result}
    except Exception as e:
        return {"result": "others", "execution_status": "error", "error_message": f"Execution error: {e}"}
    finally:
        for path, mode in original_modes.items():
            try:
                os.chmod(path, mode)
            except Exception:
                pass


def verifier_function_name(verifier_entry):
    """Mirrors awm.core.verify.run_verifier function-name selection for code mode."""
    code = verifier_entry.get("verification", {}).get("code", "")
    func_name = "verify_task_completion"
    for line in code.split("\n"):
        line = line.strip()
        if line.startswith("def verify_") and "(" in line:
            func_name = line.split("(")[0].replace("def ", "").strip()
            break
    return func_name


def run_rule(verifier_entry, initial_db_path, final_db_path, final_answer=None):
    code = verifier_entry.get("verification", {}).get("code", "")
    if not code or not isinstance(code, str) or len(code.strip()) < 10:
        return {"result": "others", "execution_status": "error", "error_message": "No valid verifier code found"}
    return execute_code_verifier(code, verifier_function_name(verifier_entry),
                                 initial_db_path, final_db_path, final_answer)


def load_all():
    db_rows = tools_jsonl_load(DB_FILE)
    sample_rows = tools_jsonl_load(SAMPLE_FILE)
    verifier_rows = tools_jsonl_load(VERIFIER_FILE)
    tasks_rows = tools_jsonl_load(DATA_ROOT / "gen_tasks.jsonl")
    return db_rows, sample_rows, verifier_rows, tasks_rows

def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    from datetime import datetime, timedelta

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    # Calculate the cutoff date (6 months ago from today)
    # AWM repair: sample data is seeded relative to runtime "now", so use
    # the actual runtime date instead of a hardcoded generator-era date.
    today = datetime.now()
    six_months_ago = today - timedelta(days=182)  # approximately 6 months
    cutoff_date_str = six_months_ago.strftime('%Y-%m-%d')

    # Find all unread items with 'machine-learning' tag in initial database
    # Tag 'machine-learning' has id=4 and belongs to user_id=1
    initial_ml_unread_query = """
        SELECT DISTINCT i.id, i.created_at, i.status
        FROM items i
        JOIN item_tags it ON i.id = it.item_id
        JOIN tags t ON it.tag_id = t.id
        WHERE t.name = 'machine-learning'
        AND t.user_id = 1
        AND i.user_id = 1
        AND i.status = 'unread'
        ORDER BY i.id
    """

    initial_ml_unread = safe_query(initial_db_path, initial_ml_unread_query)

    if not initial_ml_unread:
