def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    import re
    import json

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cur = conn.cursor()
            cur.execute(query, params)
            rows = cur.fetchall()
            conn.close()
            return rows
        except Exception:
            return []

    # Helper: parse final_answer to mapping {event_id:int -> set(pass_ids:int)}
    def parse_event_pass_map(ans: str) -> dict | None:
        if not isinstance(ans, str):
            return None
        s = ans.strip()
        if not s:
            return None

        # Try to extract JSON from the answer by locating the outermost braces
        def try_json_extract(text: str):
            # Direct parse first
            try:
                return json.loads(text)
            except Exception:
                pass
            # Find first '{' and last '}'
            l = text.find('{')
            r = text.rfind('}')
            if l != -1 and r != -1 and r > l:
                blob = text[l:r+1]
                try:
                    return json.loads(blob)
                except Exception:
                    return None
            return None

        def build_map_from_obj(obj):
            # Returns dict[int, set[int]] or None
            mapping: dict[int, set[int]] = {}
            if isinstance(obj, dict):
                # Case 1: top-level keys are event IDs
                all_digit_keys = all(isinstance(k, (str,int)) and str(k).isdigit() for k in obj.keys()) and len(obj.keys())>0
                if all_digit_keys:
                    for k, v in obj.items():
                        try:
                            eid = int(k)
                        except Exception:
                            continue
                        pass_ids: set[int] = set()
                        if isinstance(v, list):
                            for item in v:
                                if isinstance(item, dict):
                                    # look for id or pass_id
                                    for key in ("pass_id", "id"):
                                        if key in item and isinstance(item[key], (int, str)) and str(item[key]).isdigit():
                                            pass_ids.add(int(item[key]))
                                            break
                                elif isinstance(item, (int, str)) and str(item).isdigit():
                                    pass_ids.add(int(item))
                        if pass_ids:
                            mapping[eid] = pass_ids
                    if mapping:
                        return mapping
                # Case 2: look for a list value containing groups with event_id and passes
                for v in obj.values():
                    if isinstance(v, list):
                        tmp = build_map_from_list(v)
                        if tmp:
                            return tmp
                return None
            elif isinstance(obj, list):
                return build_map_from_list(obj)
            return None

        def build_map_from_list(lst):
            mapping: dict[int, set[int]] = {}
            for item in lst:
                if isinstance(item, dict):
                    # Expect fields like event_id / eventId and passes list
                    eid = None
                    for k in ("event_id", "eventId", "eventID", "event"):
                        if k in item and isinstance(item[k], (int, str)) and str(item[k]).isdigit():
                            eid = int(item[k])
                            break
                    if eid is None:
                        continue
                    passes = None
                    for pk in ("passes", "accesses", "items", "entries"):
                        if pk in item and isinstance(item[pk], list):
                            passes = item[pk]
                            break
                    # If passes not present but item itself is a pass? Skip
                    if passes is None:
                        continue
                    pass_ids: set[int] = set()
                    for p in passes:
                        if isinstance(p, dict):
                            for key in ("pass_id", "id"):
                                if key in p and isinstance(p[key], (int, str)) and str(p[key]).isdigit():
                                    pass_ids.add(int(p[key]))
                                    break
                        elif isinstance(p, (int, str)) and str(p).isdigit():
                            pass_ids.add(int(p))
                    if pass_ids:
                        mapping[eid] = pass_ids
            return mapping if mapping else None

        obj = try_json_extract(s)
        if obj is not None:
            mp = build_map_from_obj(obj)
            if mp:
                return mp

        # Regex fallback: detect event groups and pass IDs by textual patterns
        # Find occurrences of event id mentions
        ev_iter = list(re.finditer(r"(?i)\b(event[_\s]*id|event)\b[^0-9]{0,3}(\d+)\b", s))
        if not ev_iter:
            return None
        # Build segments per event occurrence
        positions = [(m.start(), int(m.group(2))) for m in ev_iter]
        positions.sort()
        segments = []
        for i, (start, eid) in enumerate(positions):
            end = positions[i+1][0] if i+1 < len(positions) else len(s)
            segments.append((eid, s[start:end]))
        mapping: dict[int, set[int]] = {}
        for eid, seg in segments:
            # Capture patterns like 'pass id: N', 'access pass id N', 'pass #N'
            ids = set()
            for rx in [
                r"(?i)\b(?:pass|access(?:\s*pass)?)\b[^0-9]{0,10}\bid\b[^0-9]{0,3}(\d+)\b",
                r"(?i)\b(?:pass|access(?:\s*pass)?)\s*#\s*(\d+)\b",
                r"(?i)\b(?:pass|access(?:\s*pass)?)\b[^\n]{0,40}\b(id|pass_id)\b[^0-9]{0,3}(\d+)\b",
            ]:
                for m in re.finditer(rx, seg):
                    # If regex has two groups (like (id|pass_id) and (\d+)), last group is the number
                    num = m.group(m.lastindex)
                    if isinstance(num, str) and num.isdigit():
                        ids.add(int(num))
            if ids:
                mapping[eid] = ids
        return mapping if mapping else None

    # 1) Identify channel id for 'Indie Fridays Live'
    ch_rows = safe_query(final_db_path, "SELECT id FROM channels WHERE title = ?", ("Indie Fridays Live",))
    if len(ch_rows) != 1:
        return {"result": "others"}
    channel_id = ch_rows[0][0]

    # 2) Determine the unique viewer with an active subscription covering the entire window
    window_start = "2026-01-01 00:00:00"
    window_end = "2026-01-31 23:59:59"
    subs_rows = safe_query(
        final_db_path,
        """
        SELECT user_id FROM channel_subscriptions
        WHERE channel_id = ? AND status = 'active'
          AND start_at <= ? AND (end_at IS NULL OR end_at >= ?)
        GROUP BY user_id
        """,
        (channel_id, window_start, window_end)
    )
    if len(subs_rows) != 1:
        # Ambiguous which viewer; cannot be 100% certain
        return {"result": "others"}
    viewer_user_id = subs_rows[0][0]

    # 3) Get events in date window (any channel, per task wording)
    ev_rows = safe_query(
        final_db_path,
        "SELECT id, start_time, end_time FROM events WHERE start_time BETWEEN ? AND ? ORDER BY id",
        (window_start, window_end)
    )
    if not ev_rows:
        return {"result": "others"}
    event_ids_in_window = [r[0] for r in ev_rows]

    # 4) Compute expected valid passes for this viewer overlapping each event time and with valid statuses
    ap_rows = safe_query(
        final_db_path,
        """
        SELECT ap.id, ap.event_id, ap.access_type, ap.status, ap.valid_from, ap.valid_until
        FROM access_passes ap
        JOIN events e ON e.id = ap.event_id
        WHERE ap.user_id = ?
          AND e.start_time BETWEEN ? AND ?
          AND ap.status IN ('active','scheduled')
          AND ap.valid_until >= e.start_time
          AND ap.valid_from <= e.end_time
        ORDER BY ap.event_id, ap.id
        """,
        (viewer_user_id, window_start, window_end)
    )
    if not ap_rows:
        return {"result": "others"}

    expected_map: dict[int, set[int]] = {}
    for pid, eid, atype, status, vf, vu in ap_rows:
        expected_map.setdefault(eid, set()).add(int(pid))

    # We expect at least some passes; otherwise cannot verify
    if not expected_map:
        return {"result": "others"}

    # 5) Parse final_answer and validate grouping and pass IDs
    if not isinstance(final_answer, str) or not final_answer.strip():
        return {"result": "others"}

    parsed_map = parse_event_pass_map(final_answer)
    if not parsed_map:
        return {"result": "others"}

    # Only consider event IDs that are in the date window (ignore any other mentions)
    # Filter both maps to intersection with event_ids_in_window
    expected_keys = set(expected_map.keys())
    # Remove any entries for events with zero passes (should not exist in expected_map)
    parsed_filtered = {eid: set(pids) for eid, pids in parsed_map.items() if eid in event_ids_in_window}

    # Strict match: keys must match exactly, and pass-id sets must match exactly per event
    if set(parsed_filtered.keys()) != expected_keys:
        return {"result": "others"}
    for eid in expected_keys:
        exp_set = expected_map.get(eid, set())
        got_set = parsed_filtered.get(eid, set())
        if got_set != exp_set:
            return {"result": "others"}

    # Additional safety: ensure there are no extra event groups with IDs in window outside expected keys
    extra_in_answer = [eid for eid in parsed_map.keys() if (eid in event_ids_in_window and eid not in expected_keys)]
    if extra_in_answer:
        return {"result": "others"}

    return {"result": "complete"}

def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    from datetime import datetime, timedelta

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    # AWM repair: derive the reference date from the most recent
    # timestamps in the database (sample data is seeded relative to
    # runtime "now", so the hardcoded generator-era date went stale).
    _awm_ref_rows = safe_query(initial_db_path, """
        SELECT MAX(ts) FROM (
            SELECT MAX(updated_at) AS ts FROM orders
            UNION ALL
            SELECT MAX(created_at) AS ts FROM orders
            UNION ALL
            SELECT MAX(closet_created_at) AS ts FROM listings
        )
    """)
    try:
        reference_date = (_awm_ref_rows[0][0] if _awm_ref_rows and _awm_ref_rows[0][0]
                         else datetime.now().strftime('%Y-%m-%d %H:%M:%S'))
        ref_dt = datetime.strptime(reference_date, '%Y-%m-%d %H:%M:%S')
        threshold_date = ref_dt - timedelta(days=90)
        threshold_str = threshold_date.strftime('%Y-%m-%d %H:%M:%S')
    except Exception:
        return {"result": "others"}

    # Get active listings from main_seller (user_id=1) in initial state
    initial_query = """
        SELECT id, listing_price_cents, closet_created_at
        FROM listings
        WHERE seller_id = 1 AND status = 'active'
    """
    initial_listings = safe_query(initial_db_path, initial_query)

    if not initial_listings:
        return {"result": "others"}

    # Get all orders to identify listings that have been sold
    orders_query = "SELECT DISTINCT listing_id FROM orders"
    sold_listing_ids = set(row[0] for row in safe_query(initial_db_path, orders_query))

    # Identify listings that qualify for price reduction
    # Criteria: active, closet_created_at > 90 days ago, never sold
    qualifying_listings = []
    for listing_id, price_cents, closet_created_at in initial_listings:
        # Skip if listing has been sold
        if listing_id in sold_listing_ids:
            continue

        # Check if closet_created_at is more than 90 days ago
        try:
            if closet_created_at and closet_created_at < threshold_str:
                qualifying_listings.append((listing_id, price_cents))
        except Exception:
            continue

    # AWM repair: no qualifying listings means nothing needed a price
    # reduction (on this data the >90-day active listings have all been
    # sold) - fall through to the unchanged-price check below, which
    # accepts an untouched DB and rejects price changes on
    # non-qualifying listings.

    # Get final state of all listings from seller_id=1
    final_query = """
        SELECT id, listing_price_cents
        FROM listings
        WHERE seller_id = 1
    """
    final_listings = safe_query(final_db_path, final_query)

    if not final_listings:
        return {"result": "others"}

    # Create a map of final prices
    final_prices = {listing_id: price for listing_id, price in final_listings}

    # Verify that all qualifying listings have 20% price reduction
    all_reduced_correctly = True
    for listing_id, initial_price in qualifying_listings:
        if listing_id not in final_prices:
            return {"result": "others"}

        final_price = final_prices[listing_id]
        expected_price = int(initial_price * 0.8)

        # Allow for minor rounding differences (within 1 cent)
        if abs(final_price - expected_price) > 1:
            all_reduced_correctly = False
            break

    if not all_reduced_correctly:
        return {"result": "others"}

    # Verify that non-qualifying listings from seller_id=1 remain unchanged
    initial_prices_map = {listing_id: price for listing_id, price, _ in initial_listings}

    for listing_id, initial_price, _ in initial_listings:
        # Skip qualifying listings (already checked)
        if any(ql[0] == listing_id for ql in qualifying_listings):
            continue

        if listing_id in final_prices:
            # Non-qualifying listings should have unchanged prices
            if final_prices[listing_id] != initial_price:
                return {"result": "others"}

    # All checks passed
    return {"result": "complete"}

def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    import re

    # Helper to safely query database
    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    def parse_float(num_str: str):
        if num_str is None:
            return None
        s = str(num_str).strip()
        # Remove currency symbol and commas/spaces
        s = s.replace('$', '').replace(',', '').strip()
        # Must be a valid number
        m = re.fullmatch(r"[-+]?\d*(?:\.\d+)?", s)
        if not m or s == '' or s == '+' or s == '-':
            return None
        try:
            return float(s)
        except Exception:
            return None

    # 1) Build ground truth from final DB
    # Get community id for 'Hillcrest Estates'
    comm_rows = safe_query(final_db_path, "SELECT id FROM communities WHERE name = ?", ("Hillcrest Estates",))
    if not comm_rows or not comm_rows[0] or comm_rows[0][0] is None:
        return {"result": "others"}
    community_id = comm_rows[0][0]

    # Get unit id for unit_number '3C' within this community
    unit_rows = safe_query(final_db_path, "SELECT id FROM units WHERE community_id = ? AND unit_number = ?", (community_id, '3C'))
    if not unit_rows or not unit_rows[0] or unit_rows[0][0] is None:
        return {"result": "others"}
    unit_id = unit_rows[0][0]

    # Get all invoices for this unit ordered by billing_period DESC
    inv_rows_desc = safe_query(final_db_path, "SELECT id, billing_period, amount_due, due_date, payment_status FROM dues_invoices WHERE unit_id = ? ORDER BY billing_period DESC", (unit_id,))
    if not inv_rows_desc or len(inv_rows_desc) < 6:
        # Need at least 6 to satisfy 'last 6 months'
        return {"result": "others"}

    latest6 = inv_rows_desc[:6]

    # Prepare expected data structures
    expected_periods = []
    expected_details = {}  # period -> dict(amount_due, due_date, payment_status, invoice_id)

    outstanding_total = 0.0
    unpaid_count = 0

    for (inv_id, period, amt_due, due_date, status) in latest6:
        if period is None or due_date is None or status is None:
            return {"result": "others"}
        expected_periods.append(period)
        expected_details[period] = {
            'invoice_id': inv_id,
            'amount_due': float(amt_due) if amt_due is not None else None,
            'due_date': str(due_date),
            'payment_status': str(status).lower()
        }
        st = str(status).lower()
        if st == 'unpaid':
            unpaid_count += 1
            outstanding_total += float(amt_due)
        elif st == 'partial':
            pay_sum_rows = safe_query(final_db_path, "SELECT COALESCE(SUM(amount_paid), 0.0) FROM invoice_payments WHERE invoice_id = ?", (inv_id,))
            paid_sum = 0.0
            if pay_sum_rows and pay_sum_rows[0] and pay_sum_rows[0][0] is not None:
                try:
                    paid_sum = float(pay_sum_rows[0][0])
                except Exception:
                    paid_sum = 0.0
            remaining = float(amt_due) - paid_sum
            if remaining < 0:
                remaining = 0.0
            outstanding_total += remaining
        elif st in ('paid', 'waived'):
            # no outstanding
            pass
        else:
            # Unknown status - be conservative
            return {"result": "others"}

    # 2) Parse final_answer for six invoices and summary values
    if final_answer is None:
        return {"result": "others"}
    text = str(final_answer)
    if text.strip() == '':
        return {"result": "others"}

    # Regex to capture each invoice block with labeled fields
    # We keep bounded wildcards between labels to avoid crossing entries.
    invoice_pattern = re.compile(
        r"billing[_\s\-]?period\s*[:\-]?\s*(?P<period>20\d{2}-(0[1-9]|1[0-2]))" \
        r".{0,200}?amount[_\s\-]?due\s*[:\-]?\s*\$?\s*(?P<amount>(?:\d{1,3}(?:,\d{3})*|\d+)(?:\.\d{1,2})?)" \
        r".{0,200}?due[_\s\-]?date\s*[:\-]?\s*(?P<duedate>20\d{2}-(0[1-9]|1[0-2])-[0-3]\d)" \
        r".{0,200}?payment[_\s\-]?status\s*[:\-]?\s*(?P<status>paid|unpaid|partial|waived)",
        re.IGNORECASE | re.DOTALL
    )

    extracted = []
    for m in invoice_pattern.finditer(text):
        period = m.group('period')
        amount_s = m.group('amount')
        duedate = m.group('duedate')
        status = m.group('status').lower() if m.group('status') else None
        amt = parse_float(amount_s)
        if period and duedate and status and (amt is not None):
            extracted.append({'period': period, 'amount_due': amt, 'due_date': duedate, 'payment_status': status})

    # We require exactly 6 invoice entries to assert 'last 6 months' were provided
    if len(extracted) != 6:
        return {"result": "others"}

    # Validate periods set matches expected exactly (order may differ)
    expected_set = set(expected_periods)
    extracted_set = set([e['period'] for e in extracted])
    if extracted_set != expected_set:
        return {"result": "others"}

    # Validate each invoice's fields match DB
    for e in extracted:
        period = e['period']
        if period not in expected_details:
            return {"result": "others"}
        exp = expected_details[period]
        # amount_due must match exactly within 0.01
        if exp['amount_due'] is None:
            return {"result": "others"}
        if abs(float(exp['amount_due']) - float(e['amount_due'])) > 0.01:
            return {"result": "others"}
        # due_date must match exactly
        if str(exp['due_date']) != str(e['due_date']):
            return {"result": "others"}
        # payment_status must match (case-insensitive)
        if str(exp['payment_status']).lower() != str(e['payment_status']).lower():
            return {"result": "others"}

    # Extract total outstanding balance reported
    total_patterns = [
        re.compile(r"\btotal\s+outstanding\s+balance\s*[:\-]?\s*\$?\s*((?:\d{1,3}(?:,\d{3})*|\d+)(?:\.\d{1,2})?)", re.IGNORECASE),
        re.compile(r"\boutstanding\s+balance\s*[:\-]?\s*\$?\s*((?:\d{1,3}(?:,\d{3})*|\d+)(?:\.\d{1,2})?)", re.IGNORECASE)
    ]
    reported_total = None
    for pat in total_patterns:
        mt = pat.search(text)
        if mt:
            reported_total = parse_float(mt.group(1))
            break
    if reported_total is None:
        return {"result": "others"}

    # Extract count of unpaid invoices reported
    count_patterns = [
        re.compile(r"\b(?:number|count)\s+of\s+unpaid\s+invoices\s*[:\-]?\s*(\d+)", re.IGNORECASE),
        re.compile(r"\bunpaid\s+invoices\s*[:\-]?\s*(\d+)\b", re.IGNORECASE),
        re.compile(r"\bcount\s+of\s+invoices\s+.*?unpaid\s*[:\-]?\s*(\d+)", re.IGNORECASE | re.DOTALL),
        re.compile(r"\bunpaid\s+count\s*[:\-]?\s*(\d+)\b", re.IGNORECASE)
    ]
    reported_unpaid = None
    for cp in count_patterns:
        mc = cp.search(text)
        if mc:
            try:
                reported_unpaid = int(mc.group(1))
            except Exception:
                reported_unpaid = None
            if reported_unpaid is not None:
                break
    if reported_unpaid is None:
        return {"result": "others"}

    # Final validations of computed vs reported
    if abs(float(outstanding_total) - float(reported_total)) > 0.01:
        return {"result": "others"}
    if int(unpaid_count) != int(reported_unpaid):
        return {"result": "others"}

    return {"result": "complete"}

def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    import re

    # Safe DB query helper
    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            conn.row_factory = sqlite3.Row
            cur = conn.cursor()
            cur.execute(query, params)
            rows = cur.fetchall()
            conn.close()
            return rows
        except Exception:
            return []

    # Parse YYYY-MM-DD safely into (y, m, d); return None on failure
    def parse_date_ymd(s: str):
        if not isinstance(s, str):
            return None
        m = re.fullmatch(r"(\d{4})-(\d{2})-(\d{2})", s.strip())
        if not m:
            return None
        y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
        if mo < 1 or mo > 12 or d < 1 or d > 31:
            return None
        return (y, mo, d)

    # Full months between two dates inclusive of month boundaries; floor months elapsed
    def months_between(start_ymd, end_ymd):
        if not start_ymd or not end_ymd:
            return None
        y1, m1, d1 = start_ymd
        y2, m2, d2 = end_ymd
        base = (y2 - y1) * 12 + (m2 - m1)
        if d2 < d1:
            base -= 1
        return base

    # Extract a money-like value as float from text segment; returns None if not found/invalid
    def extract_money_value(seg: str):
        if not isinstance(seg, str):
            return None
        m = re.search(r"\$?\s*([0-9][\d,]*(?:\.\d+)?)", seg)
        if not m:
            return None
        val_str = m.group(1).replace(",", "").strip()
        if not re.fullmatch(r"\d+(?:\.\d+)?", val_str):
            return None
        try:
            return float(val_str)
        except Exception:
            return None

    # Extract an average months value near a type mention
    def extract_avg_months(seg: str):
        if not isinstance(seg, str):
            return None
        m = re.search(r"(?:avg|average)[^0-9-]*([0-9]+(?:\.[0-9]+)?)\s*month", seg, flags=re.IGNORECASE)
        if not m:
            return None
        s = m.group(1)
        if not re.fullmatch(r"\d+(?:\.\d+)?", s):
            return None
        try:
            return float(s)
        except Exception:
            return None

    # Try to find revenue and avg months for a given asset type name in the final_answer
    def find_type_metrics(text: str, type_name: str):
        if not isinstance(text, str) or not isinstance(type_name, str):
            return (None, None)
        name_pat = re.escape(type_name)
        # Primary: regex over entire text allowing arbitrary formatting
        pat = rf"{name_pat}.*?(\$?\s*[0-9][\d,]*(?:\\.\d+)?).*?(?:avg|average)[^0-9-]*([0-9]+(?:\\.[0-9]+)?)\\s*month"
        m = re.search(pat, text, flags=re.IGNORECASE | re.DOTALL)
        if m:
            rev = extract_money_value(m.group(1))
            try:
                avgm = float(m.group(2))
            except Exception:
                avgm = None
            return (rev, avgm)
        # Fallback: scan nearby lines
        lines = text.splitlines()
        for i, line in enumerate(lines):
            if type_name.lower() in line.lower():
                seg = line
                if i + 1 < len(lines):
                    seg += " " + lines[i + 1]
                if i + 2 < len(lines):
                    seg += " " + lines[i + 2]
                rev = None
                # Prefer revenue preceded by the word revenue
                mrev = re.search(r"revenue[^0-9$]*([\$]?\s*[0-9][\d,]*(?:\.\d+)?)", seg, flags=re.IGNORECASE)
                if mrev:
                    rev = extract_money_value(mrev.group(1))
                if rev is None:
                    rev = extract_money_value(seg)
                avgm = extract_avg_months(seg)
                if rev is not None and avgm is not None:
                    return (rev, avgm)
        return (None, None)

    # Choose DB to read from (prefer final)
    db_path = final_db_path if final_db_path else initial_db_path
    if not db_path:
        return {"result": "others"}

    # Load asset types
    at_rows = safe_query(db_path, "SELECT id, name FROM asset_types", ())
    type_id_to_name = {row["id"]: row["name"] for row in at_rows} if at_rows else {}
    if not type_id_to_name:
        return {"result": "others"}

    # Load assets
    a_rows = safe_query(db_path, "SELECT id, asset_type_id, asset_tag, purchase_date FROM assets", ())
    if not a_rows:
        return {"result": "others"}

    # Compute ages as of 2025-12-31
    end_ymd = parse_date_ymd("2025-12-31")
    if not end_ymd:
        return {"result": "others"}

    assets_info = []
    for r in a_rows:
        pid = r["id"]
        tid = r["asset_type_id"]
        tag = r["asset_tag"] if isinstance(r["asset_tag"], str) else ""
        pdate = r["purchase_date"] if isinstance(r["purchase_date"], str) else None
        symd = parse_date_ymd(pdate) if pdate else None
        mths = months_between(symd, end_ymd) if symd else None
        assets_info.append({"id": pid, "type_id": tid, "tag": tag, "purchase_date": pdate, "age_months": mths})

    # Qualifying assets: age >= 60 months
    qualifying = [a for a in assets_info if isinstance(a.get("age_months"), int) and a["age_months"] >= 60]
    if not qualifying:
        return {"result": "others"}

    qual_ids = [a["id"] for a in qualifying]
    qual_tags = [a["tag"] for a in qualifying if a.get("tag")] 

    # Revenue by asset (restricted to qualifying assets)
    if qual_ids:
        # Build parameter placeholders safely
        ph = ",".join(["?"] * len(qual_ids))
        r_rows = safe_query(db_path, f"SELECT r.asset_id, r.revenue_amount FROM revenue_by_asset r WHERE r.asset_id IN ({ph})", tuple(qual_ids))
    else:
        r_rows = []

    revenue_by_asset = {}
    for r in r_rows:
        aid = r["asset_id"]
        amt = r["revenue_amount"] if r["revenue_amount"] is not None else 0.0
        if not isinstance(amt, (int, float)):
            continue
        revenue_by_asset[aid] = revenue_by_asset.get(aid, 0.0) + float(amt)

    # Aggregate by type for qualifying assets
    type_to_revenue = {}
    type_to_ages = {}
    for a in qualifying:
        tid = a["type_id"]
        type_to_ages.setdefault(tid, []).append(a["age_months"])
        rev = float(revenue_by_asset.get(a["id"], 0.0))
        type_to_revenue[tid] = type_to_revenue.get(tid, 0.0) + rev

    # Build top 5 list by revenue desc
    type_summaries = []
    for tid, ages in type_to_ages.items():
        name = type_id_to_name.get(tid, str(tid))
        if not ages or not name:
            continue
        avg_age = sum(ages) / len(ages)
        total_rev = float(type_to_revenue.get(tid, 0.0))
        type_summaries.append({"type_id": tid, "name": name, "total_revenue": total_rev, "avg_age_months": avg_age})

    if not type_summaries:
        return {"result": "others"}

    # Sort by revenue desc, then name for determinism
    type_summaries.sort(key=lambda x: (-x["total_revenue"], x["name"]))
    top5 = type_summaries[:5]

    # Begin validating final_answer text
    if not isinstance(final_answer, str) or not final_answer.strip():
        return {"result": "others"}
    text = final_answer

    # Must mention cutoff date and 5-year (or 60 months) condition
    if "2025-12-31" not in text:
        return {"result": "others"}
    cond_pat = re.compile(r"(older\s*than\s*5\s*years|over\s*5\s*years|>=\s*5\s*years|at\s*least\s*5\s*years|60\s*months)", re.IGNORECASE)
    if not cond_pat.search(text):
        return {"result": "others"}

    # Must contain both section cues
    if not re.search(r"asset[\s_-]*age[\s_-]*report", text, flags=re.IGNORECASE):
        return {"result": "others"}
    if not re.search(r"revenue[\s_-]*by[\s_-]*asset[\s_-]*type", text, flags=re.IGNORECASE):
        return {"result": "others"}

    # Ensure all qualifying asset tags are present
    for tag in qual_tags:
        if not tag:
            return {"result": "others"}
        if re.search(re.escape(tag), text, flags=re.IGNORECASE) is None:
            return {"result": "others"}

    # Validate each top 5 asset type has correct total revenue and average age months
    for entry in top5:
        tname = entry["name"]
        expected_rev = float(entry["total_revenue"])
        expected_avg = float(entry["avg_age_months"])
        found_rev, found_avg = find_type_metrics(text, tname)
        # Require both metrics found
        if found_rev is None or found_avg is None:
            return {"result": "others"}
        # Compare with tolerant formatting; exact numeric equality within small tolerance
        if not isinstance(found_rev, (int, float)) or not isinstance(found_avg, (int, float)):
            return {"result": "others"}
        if abs(found_rev - expected_rev) > 0.5:
            return {"result": "others"}
        if abs(found_avg - expected_avg) > 0.5:
            return {"result": "others"}

    return {"result": "complete"}

# scenario=task_management_8 task_idx=6
# task: For volunteer 'Alex Martinez', self-sign them up for all open 'Kitchen Helper' shifts at the 'Downtown Shelter' between January 15 and January 31, 2026 that do not conflict with their existing assignments or stated availability.
def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    from datetime import datetime, time

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    # Step 1: Find Alex Martinez's volunteer_id
    alex_query = "SELECT id FROM volunteers WHERE first_name = 'Alex' AND last_name = 'Martinez'"
    alex_result = safe_query(final_db_path, alex_query)
    if not alex_result:
        return {"result": "others"}
    alex_id = alex_result[0][0]

    # Step 2: Find Kitchen Helper role_id
    role_query = "SELECT id FROM roles WHERE name = 'Kitchen Helper'"
    role_result = safe_query(final_db_path, role_query)
    if not role_result:
        return {"result": "others"}
    kitchen_helper_role_id = role_result[0][0]

    # Step 3: Find Downtown Shelter location_id (specifically Downtown Kitchen)
    location_query = "SELECT id FROM locations WHERE name IN ('Downtown Shelter', 'Downtown Kitchen') AND address LIKE '123 Main St%'"
    location_result = safe_query(final_db_path, location_query)
    if not location_result:
        return {"result": "others"}
    valid_location_ids = [row[0] for row in location_result]

    # Step 4: Find all Kitchen Helper shifts at Downtown Shelter between Jan 15-31, 2026
    target_shifts_query = """
        SELECT id, start_datetime, end_datetime, location_id
        FROM shifts
        WHERE role_id = ?
        AND location_id IN ({0})
        AND start_datetime >= '2026-01-15 00:00:00'
        AND start_datetime <= '2026-01-31 23:59:59'
        AND status = 'Open'
    """.format(','.join('?' * len(valid_location_ids)))
    target_shifts = safe_query(final_db_path, target_shifts_query, (kitchen_helper_role_id,) + tuple(valid_location_ids))

    if not target_shifts:
        return {"result": "others"}

    target_shift_ids = [shift[0] for shift in target_shifts]

    # Step 5: Get Alex's existing assignments in initial state
    initial_assignments_query = """
        SELECT sa.shift_id, s.start_datetime, s.end_datetime
        FROM shift_assignments sa
        JOIN shifts s ON sa.shift_id = s.id
        WHERE sa.volunteer_id = ?
    """
    initial_assignments = safe_query(initial_db_path, initial_assignments_query, (alex_id,))
    initial_shift_ids = {row[0] for row in initial_assignments}

    # Step 6: Get Alex's availability
    availability_query = "SELECT day_of_week, start_time, end_time FROM volunteer_availability WHERE volunteer_id = ?"
    availability = safe_query(final_db_path, availability_query, (alex_id,))

    # Create availability map
    availability_map = {}
    for day, start_str, end_str in availability:
        availability_map[day] = (start_str, end_str)

    # Step 7: Determine eligible shifts (no conflicts, matches availability)
    def parse_datetime(dt_str):
        try:
            return datetime.strptime(dt_str, '%Y-%m-%d %H:%M:%S')
        except:
            return None

    def parse_time(time_str):
        try:
            return datetime.strptime(time_str, '%H:%M:%S').time()
        except:
            return None

    def shifts_overlap(start1, end1, start2, end2):
        return start1 < end2 and start2 < end1

    def is_within_availability(shift_start, shift_end, avail_day_map):
        weekday = shift_start.weekday()
        if weekday not in avail_day_map:
            return False
        avail_start_str, avail_end_str = avail_day_map[weekday]
        avail_start = parse_time(avail_start_str)
        avail_end = parse_time(avail_end_str)
        if not avail_start or not avail_end:
            return False
        shift_start_time = shift_start.time()
        shift_end_time = shift_end.time()
        return shift_start_time >= avail_start and shift_end_time <= avail_end

    eligible_shift_ids = []
    for shift_id, start_str, end_str, loc_id in target_shifts:
        shift_start = parse_datetime(start_str)
        shift_end = parse_datetime(end_str)
        if not shift_start or not shift_end:
            continue

        # Check if already assigned in initial state
        if shift_id in initial_shift_ids:
            continue

        # Check for conflicts with existing assignments
        has_conflict = False
        for _, existing_start_str, existing_end_str in initial_assignments:
            existing_start = parse_datetime(existing_start_str)
            existing_end = parse_datetime(existing_end_str)
            if existing_start and existing_end:
                if shifts_overlap(shift_start, shift_end, existing_start, existing_end):
                    has_conflict = True
                    break

        if has_conflict:
            continue

        # Check availability
        if availability_map and not is_within_availability(shift_start, shift_end, availability_map):
            continue

        eligible_shift_ids.append(shift_id)

    # Step 8: Get final assignments for Alex
    final_assignments_query = """
        SELECT shift_id, source, status
        FROM shift_assignments
        WHERE volunteer_id = ?
    """
    final_assignments = safe_query(final_db_path, final_assignments_query, (alex_id,))
    final_shift_ids = {row[0] for row in final_assignments}

    # Step 9: Find newly created assignments
    new_assignments = []
    for shift_id, source, status in final_assignments:
        if shift_id not in initial_shift_ids and shift_id in target_shift_ids:
            new_assignments.append((shift_id, source, status))

    # Step 10: Verify all eligible shifts were assigned
    if not eligible_shift_ids:
        # No eligible shifts - task is complete if no new assignments were made
        if not new_assignments:
            return {"result": "complete"}
        return {"result": "others"}

    # Check all eligible shifts were assigned
    assigned_eligible_shifts = [sa[0] for sa in new_assignments if sa[0] in eligible_shift_ids]

    if set(assigned_eligible_shifts) != set(eligible_shift_ids):
        return {"result": "others"}

    # Step 11: Verify all new assignments are marked with source='Self'
    for shift_id, source, status in new_assignments:
        if source != 'Self':
            return {"result": "others"}

    # Step 12: Verify no ineligible shifts were assigned
    for shift_id, source, status in new_assignments:
        if shift_id not in eligible_shift_ids:
            return {"result": "others"}

    return {"result": "complete"}

def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    import re
    from datetime import datetime, date

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            conn.row_factory = sqlite3.Row
            cur = conn.cursor()
            cur.execute(query, params)
            rows = cur.fetchall()
            conn.close()
            return rows
        except Exception:
            return []

    def parse_date_str(s: str) -> date | None:
        if not s or not isinstance(s, str):
            return None
        s = s.strip()
        # Try common ISO formats
        for fmt in ("%Y-%m-%d", "%Y-%m-%d %H:%M:%S", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%d %H:%M:%S.%f", "%Y-%m-%dT%H:%M:%S.%f"):
            try:
                dt = datetime.strptime(s, fmt)
                return dt.date()
            except Exception:
                continue
        # If string may already be date-like but with timezone, strip timezone info
        tz_idx = max(s.find("+"), s.find("-", 10))
        if tz_idx > 0:
            try:
                dt = datetime.fromisoformat(s[:tz_idx])
                return dt.date()
            except Exception:
                pass
        try:
            dt = datetime.fromisoformat(s)
            return dt.date()
        except Exception:
            return None

    def max_nullable_date(dates: list[date]) -> date | None:
        vals = [d for d in dates if isinstance(d, date)]
        if not vals:
            return None
        return max(vals)

    def get_reference_date(db_path: str) -> date | None:
        # Collect maximum dates from several relevant tables/columns
        candidates: list[date] = []
        # donations.donated_at
        rows = safe_query(db_path, "SELECT MAX(donated_at) AS m FROM donations")
        if rows and rows[0][0] is not None:
            d = parse_date_str(rows[0][0])
            if d: candidates.append(d)
        # campaigns.updated_at
        rows = safe_query(db_path, "SELECT MAX(updated_at) AS m FROM campaigns")
        if rows and rows[0][0] is not None:
            d = parse_date_str(rows[0][0])
            if d: candidates.append(d)
        # recurring_donation_schedules.updated_at and created_at
        rows = safe_query(db_path, "SELECT MAX(updated_at) AS m, MAX(created_at) AS c FROM recurring_donation_schedules")
        if rows:
            if rows[0][0] is not None:
                d = parse_date_str(rows[0][0])
                if d: candidates.append(d)
            if rows[0][1] is not None:
                d = parse_date_str(rows[0][1])
                if d: candidates.append(d)
        # payout_batches.scheduled_payout_date
        rows = safe_query(db_path, "SELECT MAX(scheduled_payout_date) AS m FROM payout_batches")
        if rows and rows[0][0] is not None:
            d = parse_date_str(rows[0][0])
            if d: candidates.append(d)
        # campaign_updates.posted_at
        rows = safe_query(db_path, "SELECT MAX(posted_at) AS m FROM campaign_updates")
        if rows and rows[0][0] is not None:
            d = parse_date_str(rows[0][0])
            if d: candidates.append(d)
        return max_nullable_date(candidates)

    def first_day_next_month(d: date) -> str:
        # Returns YYYY-MM-DD for the first day of the next month
        year = d.year
        month = d.month
        if month == 12:
            return f"{year+1:04d}-01-01"
        else:
            return f"{year:04d}-{month+1:02d}-01"

    def get_current_user_id(db_path: str) -> int | None:
        # Prefer username 'current_user'
        rows = safe_query(db_path, "SELECT id FROM users WHERE username = ?", ("current_user",))
        if len(rows) == 1 and rows[0][0] is not None:
            try:
                return int(rows[0][0])
            except Exception:
                return None
        # Fallback: unique user with role donor_owner in profile_data
        rows = safe_query(db_path, "SELECT id FROM users WHERE profile_data LIKE '%donor_owner%'")
        if len(rows) == 1 and rows[0][0] is not None:
            try:
                return int(rows[0][0])
            except Exception:
                return None
        return None

    def get_campaign_id_by_name(db_path: str, name: str) -> int | None:
        rows = safe_query(db_path, "SELECT id FROM campaigns WHERE name = ?", (name,))
        if len(rows) != 1:
            return None
        try:
            return int(rows[0][0])
        except Exception:
            return None

    def get_payment_method_id(db_path: str, user_id: int, brand: str, last4: str) -> int | None:
        rows = safe_query(db_path, "SELECT id FROM payment_methods WHERE user_id = ? AND UPPER(brand) = UPPER(?) AND last4 = ?", (user_id, brand, last4))
        if len(rows) != 1:
            return None
        try:
            return int(rows[0][0])
        except Exception:
            return None

    def count_matching_schedules(db_path: str, user_id: int, campaign_id: int, payment_method_id: int, start_date: str) -> int:
        q = (
            "SELECT COUNT(1) FROM recurring_donation_schedules "
            "WHERE user_id = ? AND campaign_id = ? AND payment_method_id = ? "
            "AND CAST(amount AS REAL) = 50.0 AND UPPER(currency) = 'USD' "
            "AND interval_unit = 'month' AND interval_count = 1 "
            "AND start_date = ? AND status = 'active' "
            "AND stop_when_campaign_complete = 1 AND end_date IS NULL"
        )
        rows = safe_query(db_path, q, (user_id, campaign_id, payment_method_id, start_date))
        if not rows:
            return 0
        try:
            return int(rows[0][0])
        except Exception:
            return 0

    # 1) Resolve entities in final DB for determinism
    user_id = get_current_user_id(final_db_path)
    if user_id is None:
        return {"result": "others"}

    campaign_id = get_campaign_id_by_name(final_db_path, "Community Health Clinic Supplies")
    if campaign_id is None:
        return {"result": "others"}

    pm_id = get_payment_method_id(final_db_path, user_id, "VISA", "4242")
    if pm_id is None:
        return {"result": "others"}

    # 2) Compute expected start_date from reference date
    ref_date = get_reference_date(final_db_path)
    if ref_date is None:
        # Fallback to initial DB
        ref_date = get_reference_date(initial_db_path)
    if ref_date is None:
        return {"result": "others"}
    expected_start = first_day_next_month(ref_date)

    # 3) Count matching schedules in both DBs
    init_user_id = get_current_user_id(initial_db_path)
    # If user_id differs across DBs or missing in initial, we still proceed with final verification but need count in initial; if missing, treat as 0 to avoid false positives
    if init_user_id is None:
        init_user_id = user_id
    init_campaign_id = get_campaign_id_by_name(initial_db_path, "Community Health Clinic Supplies")
    if init_campaign_id is None:
        init_campaign_id = campaign_id
    init_pm_id = get_payment_method_id(initial_db_path, init_user_id, "VISA", "4242")
