        target_local_time = time(20, 30, 0)
        if days_ahead == 0 and (local_dt.time() >= target_local_time):
            days_ahead = 7
        target_date = (local_dt.date() + timedelta(days=days_ahead))
        target_local_dt = datetime.combine(target_date, target_local_time, tzinfo=tz)
