    # 3) Ensure media items exist in final DB for given external IDs
    target_ext_ids = ("tt0078748", "tt0081505")
    mi_rows = safe_query(final_db_path, "SELECT id, external_id FROM media_items WHERE external_id IN (?, ?)", target_ext_ids)
    ext_to_id = {row[1]: row[0] for row in mi_rows if row[1] in target_ext_ids}
    if len(ext_to_id) != 2:
        return {"result": "others"}
    req_media_ids = {ext_to_id["tt0078748"], ext_to_id["tt0081505"]}

    # 4) Find candidate new rooms created by current user with exact specified attributes
    room_rows = safe_query(
