        # 5) Verify both media items are linked to this room
        rmi_rows = safe_query(final_db_path, "SELECT media_item_id FROM room_media_items WHERE room_id = ?", (room_id,))
        linked_ids = {row[0] for row in rmi_rows if row and row[0] is not None}
        has_required_links = req_media_ids.issubset(linked_ids)
        if not has_required_links:
            continue

        # 6) Verify a scheduled room_session exists for this room at next Friday 8:30 PM local time, computed from session.created_at
        sess_rows = safe_query(
            final_db_path,
            "SELECT id, start_time_utc, status, host_user_id, created_at FROM room_sessions WHERE room_id = ? AND status = 'scheduled'",
            (room_id,)
        )
        session_ok = False
        for s in sess_rows:
