            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    # Calculate the cutoff date (6 months ago from today)
    # AWM repair: sample data is seeded relative to runtime "now", so use
    # the actual runtime date instead of a hardcoded generator-era date.
    today = datetime.now()
    six_months_ago = today - timedelta(days=182)  # approximately 6 months
    cutoff_date_str = six_months_ago.strftime('%Y-%m-%d')

    # Find all unread items with 'machine-learning' tag in initial database
    # Tag 'machine-learning' has id=4 and belongs to user_id=1
    initial_ml_unread_query = """
        SELECT DISTINCT i.id, i.created_at, i.status
        FROM items i
        JOIN item_tags it ON i.id = it.item_id
        JOIN tags t ON it.tag_id = t.id
        WHERE t.name = 'machine-learning'
        AND t.user_id = 1
        AND i.user_id = 1
        AND i.status = 'unread'
        ORDER BY i.id
    """

    initial_ml_unread = safe_query(initial_db_path, initial_ml_unread_query)

    if not initial_ml_unread:
        # No unread ML items found, task is trivially complete
        return {"result": "complete"}

    # Identify which items should be archived (added more than 6 months ago)
    items_to_archive = []
    items_to_keep_unread = []

    for item_id, created_at, status in initial_ml_unread:
        try:
            # Parse created_at date
            created_date = datetime.strptime(created_at.split()[0], '%Y-%m-%d')
            if created_date < six_months_ago:
                items_to_archive.append(item_id)
            else:
                items_to_keep_unread.append(item_id)
        except Exception:
            # If we cannot parse date, cannot verify
            return {"result": "others"}

    # If no items to archive, task is complete if nothing changed
    if not items_to_archive:
        # Verify nothing was changed in final database
        final_ml_unread = safe_query(final_db_path, initial_ml_unread_query)
        if len(final_ml_unread) == len(initial_ml_unread):
            return {"result": "complete"}
        else:
            return {"result": "others"}

    # Check final database for each item that should be archived
    for item_id in items_to_archive:
        final_item_query = "SELECT status, archived_at FROM items WHERE id = ?"
        final_item = safe_query(final_db_path, final_item_query, (item_id,))

        if not final_item:
            # Item not found or query failed
            return {"result": "others"}

        status, archived_at = final_item[0]

        # Verify item is now archived
        if status != 'archived':
            return {"result": "others"}

        # Verify archived_at is set
        if not archived_at:
            return {"result": "others"}

    # Check that items within 6 months remain unread
    for item_id in items_to_keep_unread:
        final_item_query = "SELECT status FROM items WHERE id = ?"
        final_item = safe_query(final_db_path, final_item_query, (item_id,))

        if not final_item:
            return {"result": "others"}

        status = final_item[0][0]

        # Verify item is still unread
        if status != 'unread':
            return {"result": "others"}

    # Verify no other unrelated items were modified
    # Get all items that were unread and not in our ML list
    other_unread_query = """
        SELECT id, status
        FROM items
        WHERE user_id = 1
        AND status = 'unread'
    """

    initial_all_unread = safe_query(initial_db_path, other_unread_query)
    final_all_unread = safe_query(final_db_path, other_unread_query)

    initial_unread_ids = set([item[0] for item in initial_all_unread])
    final_unread_ids = set([item[0] for item in final_all_unread])

    # Items that should have been archived
    expected_removed = set(items_to_archive)
    # Items actually removed from unread
    actually_removed = initial_unread_ids - final_unread_ids

    # Check if exactly the right items were archived
    if expected_removed != actually_removed:
        return {"result": "others"}

    # All checks passed
    return {"result": "complete"}

