    # Get templates from final database
    final_templates = safe_query(final_db_path,
        "SELECT id, organization_id, name, is_active FROM form_templates WHERE organization_id = 1 AND name = 'New Patient Intake - Adult'"
    )

    if not final_templates:
        return {"result": "others"}

    # Find NEW template (id not in initial_template_ids) or check if existing was properly configured
    new_template = None
    for template in final_templates:
        template_id, org_id, name, is_active = template
        if template_id not in initial_template_ids:
            new_template = template
            break

    # If no new template created, check if existing template (id=1) was updated with new sections/questions
    if not new_template:
        # Since task says "create a new", we should expect a new template, but let's be flexible
