def _awm_orig_verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None, _awm_ev=None) -> dict:
    def _awm_probe_final(query, *params, **kw):
        """AWM repair: run the rule's own final-DB query and compare against the initial DB."""
        try:
            _awm_rows = safe_query(final_db_path, query, *params, **kw)
        except Exception:
            return []
        _awm_diff = True  # cannot compare -> assume a difference (stay complete)
        try:
            if isinstance(_awm_rows, (list, tuple)):
                _awm_init = safe_query(initial_db_path, query, *params, **kw)
                _awm_diff = (list(_awm_rows) != list(_awm_init))
        except Exception:
            _awm_diff = True
        try:
            _awm_ev.append(_awm_diff)
        except Exception:
            pass
        return _awm_rows
    import sqlite3
    import re

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    # Check if the auction_event exists with correct attributes
    event_query = """
        SELECT id, title, start_date, end_date, category_scope, 
               buyer_premium_percentage, payment_deadline_days, shipping_policies
        FROM auction_events
        WHERE title = ?
    """

    event_title = "Signed Movie Memorabilia – Spring Showcase"
    events = _awm_probe_final(event_query, (event_title,))

    # AWM repair: the seeded data already contains an auction_event
    # with this exact title (lots 901/902/910 already assigned to it),
    # so for a genuine completion that creates its own event and
    # reassigns the lots, the events[0] binding below would select the
    # seeded row and the lots check would test the wrong
    # auction_event_id. Prefer the event the episode itself created;
    # fall back to the seeded row when none was created (in-place
    # edits of the seeded event still verify; the newness guard
    # rejects a do-nothing episode).
    initial_event_ids = set(row[0] for row in
        safe_query(initial_db_path, event_query, (event_title,)))
    episode_events = [e for e in events if e[0] not in initial_event_ids]
    if episode_events:
        events = episode_events

    if not events:
        return {"result": "others"}

    # Get the event details
    event_id, title, start_date, end_date, category_scope, buyer_premium, payment_days, shipping_policies = events[0]

    # Verify all event attributes
    # Check dates - SQLite stores as '2025-03-01 16:00:00' format
    expected_start = "2025-03-01 16:00:00"
    expected_end = "2025-03-08 16:00:00"

    if start_date != expected_start:
        return {"result": "others"}

    if end_date != expected_end:
        return {"result": "others"}

    # Check category_scope
    if category_scope != "memorabilia":
        return {"result": "others"}

    # Check buyer_premium_percentage (allow for float comparison)
    if abs(buyer_premium - 17.0) > 0.01:
        return {"result": "others"}

    # Check payment_deadline_days
    if payment_days != 7:
        return {"result": "others"}

    # Check shipping_policies contains separate rules for posters, props, and scripts
    if not shipping_policies:
        return {"result": "others"}

    shipping_lower = shipping_policies.lower()
    has_poster_rules = "poster" in shipping_lower
    has_prop_rules = "prop" in shipping_lower
    has_script_rules = "script" in shipping_lower

    if not (has_poster_rules and has_prop_rules and has_script_rules):
        return {"result": "others"}

    # Verify lots 901, 902, 910 are assigned to this event
    lot_ids = [901, 902, 910]
    lots_query = "SELECT id, auction_event_id FROM lots WHERE id IN (?, ?, ?)"
    lots = _awm_probe_final(lots_query, tuple(lot_ids))

    if len(lots) != 3:
        return {"result": "others"}

    # Check that all three lots are assigned to the correct event
    for lot_id, auction_event_id in lots:
        if auction_event_id != event_id:
            return {"result": "others"}

    # All checks passed
    return {"result": "complete"}

